--
-- Name: actualizar_descansos_fin_de_semana(); Type: FUNCTION; Schema: attendance; Owner: ronald
--

CREATE FUNCTION attendance.actualizar_descansos_fin_de_semana() RETURNS text
    LANGUAGE plpgsql
    AS $$ -- Devuelve un resumen de texto
DECLARE
    v_mes_inicio DATE := date_trunc('month', CURRENT_DATE);
    v_mes_fin DATE := date_trunc('month', CURRENT_DATE) + '1 month'::interval; -- Exclusivo (hasta, pero sin incluir, el primer día del próx. mes)
    v_updated_rows INT;
BEGIN
    WITH updated AS (
        UPDATE attendance.attendance_control AS ac
        SET
            id_atdcode = CASE
                             WHEN EXTRACT(ISODOW FROM ac.date) = 6 THEN 21 -- Sábado
                             WHEN EXTRACT(ISODOW FROM ac.date) = 7 THEN 22 -- Domingo
                         END,
            confirmation = 0,
            editor = 0 -- 0 = Sistema/Automático
        WHERE
            -- 1. Solo procesar el mes actual
            ac.date >= v_mes_inicio
            AND ac.date <  v_mes_fin

            -- 2. Solo Sábados (6) y Domingos (7)
            AND EXTRACT(ISODOW FROM ac.date) IN (6, 7)

            -- 3. Solo actualizar si el estado NO es el deseado
            --    (Evita re-escribir filas idénticas y mejora eficiencia)
            AND (
                 (EXTRACT(ISODOW FROM ac.date) = 6 AND ac.id_atdcode != 21)
                 OR
                 (EXTRACT(ISODOW FROM ac.date) = 7 AND ac.id_atdcode != 22)
                 OR
                 ac.confirmation != 0
            )

            -- 4. CONDICIÓN: Y el empleado NO tiene un horario laboral REGULAR ESE día
            AND NOT EXISTS (
                -- Subconsulta para encontrar un TRAMO LABORAL REGULAR
                WITH ActiveSchedule AS (
                    -- Encuentra la asignación activa para este usuario/día
                    SELECT
                        us.id_sch_tpl,
                        st.schedule_type,
                        us.rotation_anchor_date,
                        (SELECT MAX(ste_inner.identifier_day)
                         FROM planilla.schedule_template_entries ste_inner
                         WHERE ste_inner.id_sch_tpl = us.id_sch_tpl AND ste_inner.state = TRUE) AS cycle_days
                    FROM planilla.user_schedules us
                    JOIN planilla.schedule_templates st ON us.id_sch_tpl = st.id_sch_tpl
                    WHERE us.id_user = ac.id_user -- Se vincula al UPDATE exterior
                      AND ac.date BETWEEN us.start_date AND COALESCE(us.end_date, ac.date)
                      AND us.state = TRUE AND st.state = TRUE
                    LIMIT 1
                ),
                TargetDay AS (
                    -- Calcula el 'identifier_day' correspondiente (sea semanal o rotativo)
                    SELECT
                        id_sch_tpl,
                        CASE
                            WHEN schedule_type = 1 THEN EXTRACT(ISODOW FROM ac.date)::smallint
                            WHEN schedule_type = 2 AND rotation_anchor_date IS NOT NULL AND cycle_days > 0 THEN
                                ( ( (ac.date::date - rotation_anchor_date::date) % cycle_days + cycle_days ) % cycle_days ) + 1
                            ELSE -1 -- Día inválido si la configuración es incorrecta
                        END AS day_to_find
                    FROM ActiveSchedule
                )
                -- Busca si existe un tramo laboral
                SELECT 1
                FROM planilla.schedule_template_entries ste
                JOIN TargetDay td ON ste.id_sch_tpl = td.id_sch_tpl
                WHERE ste.identifier_day = td.day_to_find
                  AND ste.state = TRUE
                  -- Un "día laborable" es uno que no es descanso (tiene al menos una hora)
                  AND (ste.entry_time IS NOT NULL OR ste.exit_time IS NOT NULL)
            )

            -- 5. CONDICIÓN: Y el empleado NO tiene una EXCEPCIÓN LABORAL ESE día
            AND NOT EXISTS (
                -- Subconsulta para encontrar un TRAMO LABORAL POR EXCEPCIÓN
                SELECT 1
                FROM planilla.schedule_exceptions se
                JOIN planilla.schedule_exception_blocks seb ON se.id_sch_exc = seb.id_sch_exc
                WHERE se.id_user = ac.id_user -- Se vincula al UPDATE exterior
                  AND se.exception_date = ac.date
                  AND se.state = TRUE
                  AND seb.state = TRUE
                  -- Si existe CUALQUIER bloque en la excepción, es un día laborable
            )
        RETURNING ac.id_atdctr -- Devolver los IDs actualizados
    )
    -- Contar cuántas filas se actualizaron
    SELECT count(*) INTO v_updated_rows FROM updated;

    RETURN 'Actualización de descansos completada. Filas afectadas: ' || v_updated_rows;

END;
$$;


ALTER FUNCTION attendance.actualizar_descansos_fin_de_semana() OWNER TO ronald;

