-- Name: attendance_control_mirror_105_445(); Type: FUNCTION; Schema: attendance; Owner: postgres
--

CREATE FUNCTION attendance.attendance_control_mirror_105_445() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    IF NEW.id_user = 105 THEN

        UPDATE attendance.attendance_control
        SET
            id_atdcode   = NEW.id_atdcode,
            confirmation = NEW.confirmation
        WHERE id_user = 445
          AND "date" = NEW."date";

    END IF;

    RETURN NEW;

END;
$$;


