--
-- Name: create_daily_attendance_control(); Type: FUNCTION; Schema: attendance; Owner: ronald
--

CREATE FUNCTION attendance.create_daily_attendance_control() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count_inserted INTEGER := 0;
BEGIN
    -- Insertar registros solo para usuarios activos (state = 1)
        id_user, 
        id_atdcode, 
        "date", 
        "day", 
        state, 
        editor, 
        confirmation
    )
    SELECT 
        md.id_user,
        14 AS id_atdcode,
        CURRENT_DATE AS "date",
        EXTRACT(ISODOW FROM CURRENT_DATE)::SMALLINT AS "day",  -- 📅 Día de la semana (1=Lunes, 7=Domingo)
        TRUE AS state,
        213 AS editor,                -- 👤 Editor del sistema
        1 AS confirmation             -- ✅ Confirmación inicial
    FROM planilla.mother_data md
    WHERE md.state = 1
      AND NOT EXISTS (
          SELECT 1 
          FROM attendance.attendance_control ac
          WHERE ac.id_user = md.id_user
            AND ac."date" = CURRENT_DATE
      );

    -- Obtener cuántos registros nuevos se insertaron
    GET DIAGNOSTICS v_count_inserted = ROW_COUNT;

    RETURN 'Registros creados en attendance_control: ' || v_count_inserted;
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error en create_daily_attendance_control: ' || SQLERRM;
END;
$$;


ALTER FUNCTION attendance.create_daily_attendance_control() OWNER TO ronald;

--
-- Name: create_monthly_attendance_control_restricted(); Type: FUNCTION; Schema: attendance; Owner: ronald
--

CREATE FUNCTION attendance.create_monthly_attendance_control_restricted() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count_inserted INTEGER := 0;
    v_start_date DATE := date_trunc('month', CURRENT_DATE)::DATE;
    v_end_date DATE := (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month - 1 day')::DATE;
BEGIN
    -- Insertar registros usando una serie de fechas
        id_user, 
        id_atdcode, 
        "date", 
        "day", 
        state, 
        editor, 
        confirmation
    )
    SELECT 
        md.id_user,
        CASE 
            WHEN EXTRACT(ISODOW FROM dates.d) = 7 THEN 22 -- Domingo
            WHEN EXTRACT(ISODOW FROM dates.d) = 6 THEN 21 -- Sábado
            ELSE 1                                       -- Lunes a Viernes
        END AS id_atdcode,
        dates.d AS "date",
        EXTRACT(ISODOW FROM dates.d)::SMALLINT AS "day",
        TRUE AS state,
        213 AS editor,
        0 AS confirmation
    FROM planilla.mother_data md
    CROSS JOIN generate_series(v_start_date, v_end_date, '1 day'::interval) AS dates(d)
    WHERE md.state = 1
      -- Filtro por usuarios específicos solicitado
      AND md.id_user IN (106, 107, 108, 109, 113, 115, 72, 62)
      -- Evitar duplicados
      AND NOT EXISTS (
          SELECT 1 
          FROM attendance.attendance_control ac
          WHERE ac.id_user = md.id_user
            AND ac."date" = dates.d::DATE
      );

    GET DIAGNOSTICS v_count_inserted = ROW_COUNT;

    RETURN 'Registros creados para usuarios seleccionados: ' || v_count_inserted;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION attendance.create_monthly_attendance_control_restricted() OWNER TO ronald;

--
-- Name: fn_close_today_attendance(); Type: FUNCTION; Schema: attendance; Owner: ronald
--

CREATE FUNCTION attendance.fn_close_today_attendance() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_updated INTEGER;
BEGIN
    UPDATE attendance.attendance_control ac
    SET id_atdcode = 1,
        editor     = 213
    WHERE ac."date" = CURRENT_DATE
      AND ac.id_atdcode = 23
      AND ac.id_user IN (
            SELECT id_user
            FROM attendance.v_today_valid_exits
      );

    GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
    RETURN v_rows_updated;
END;
$$;


ALTER FUNCTION attendance.fn_close_today_attendance() OWNER TO ronald;

--
-- Name: mark_attendance(bigint, character varying); Type: FUNCTION; Schema: attendance; Owner: ronald
--

CREATE FUNCTION attendance.mark_attendance(p_user_id bigint, p_mark_type character varying) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance, planilla, public'
    AS $$
DECLARE
    v_atdreg_id BIGINT;
    v_atdctr_id BIGINT;
    v_message VARCHAR := 'Operación no reconocida.';
    v_current_time TIME := CURRENT_TIME(0);
    v_reg_date DATE; -- 👈 variable para almacenar la fecha del registro
BEGIN
    -- Validar parámetros
    IF p_user_id IS NULL OR p_mark_type IS NULL OR p_mark_type NOT IN ('entry', 'exit') THEN
        RETURN 'Error: Parámetros inválidos.';
    END IF;

    -- Lógica para marcar ENTRADA
    IF p_mark_type = 'entry' THEN
        
        -- 1. Verificar si ya existe un registro de entrada para hoy
        SELECT id_atdreg, "date" INTO v_atdreg_id, v_reg_date
        FROM attendance.attendance_register
        WHERE id_user = p_user_id AND "date" = CURRENT_DATE AND state = TRUE
        LIMIT 1;

        -- Caso 1: No existe registro previo. Insertar uno nuevo.
        IF v_atdreg_id IS NULL THEN
            VALUES (p_user_id, CURRENT_DATE, EXTRACT(ISODOW FROM CURRENT_DATE), v_current_time, TRUE)
            RETURNING id_atdreg, "date" INTO v_atdreg_id, v_reg_date;
            
            v_message := 'MARCACION_OK'; -- Mensaje de éxito para nueva inserción

            -- 2. Actualizar/Crear attendance_control con el registro de asistencia
            -- Se asume que el id_atdcode 23 es "Presente" y 213 es el editor por defecto (Sistema)
            UPDATE attendance.attendance_control
            SET 
                id_atdreg = v_atdreg_id,
                id_atdcode = 23,        -- Asumiendo 23 = Presente/Asistió
                date_register = v_reg_date
            WHERE id_user = p_user_id
              AND "date" = CURRENT_DATE
            RETURNING id_atdctr INTO v_atdctr_id;

            IF v_atdctr_id IS NOT NULL THEN
                v_message := v_message || ' Control actualizado.';
            END IF;

            -- 3. Llamar al cálculo de descuento de tardanza inmediatamente
            PERFORM planilla.procesar_descuento_tardanza(v_atdreg_id, v_reg_date, p_user_id);
            v_message := v_message || ' Descuento de tardanza procesado.';


        -- Caso 2: Ya existe un registro de entrada. No hacer nada.
        ELSE
            RETURN 'ALREADY_MARKED'; -- Devolver código especial. Ya no se hace nada más.
        END IF;

    -- Lógica para marcar SALIDA
    ELSIF p_mark_type = 'exit' THEN
        -- Actualizar attendance_register
        UPDATE attendance.attendance_register
        SET exit_time = v_current_time
        WHERE id_user = p_user_id
          AND "date" = CURRENT_DATE
          AND entry_time IS NOT NULL
          AND exit_time IS NULL
          AND state = TRUE
        RETURNING id_atdreg, "date" INTO v_atdreg_id, v_reg_date;  -- 👈 capturamos los valores

        IF FOUND THEN
            -- Actualizar también attendance_control con la fecha del registro
            UPDATE attendance.attendance_control
            SET 
                date_register = v_reg_date  -- 👈 sincronizamos fecha
            WHERE id_user = p_user_id
              AND id_atdreg = v_atdreg_id;

            v_message := 'Salida registrada correctamente.';
        ELSE
            v_message := 'No se encontró registro de entrada activo para marcar salida o ya se marcó.';
        END IF;

        RETURN v_message;
    END IF;

    RETURN v_message;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error en la función mark_attendance: ' || SQLERRM;
END;
$$;


ALTER FUNCTION attendance.mark_attendance(p_user_id bigint, p_mark_type character varying) OWNER TO ronald;

--
-- Name: fn_propagate_new_report_to_users(); Type: FUNCTION; Schema: bi_i; Owner: ronald
--

CREATE FUNCTION bi_i.fn_propagate_new_report_to_users() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insertamos en la tabla de asignaciones (bii_group_assigned)
    SELECT 
        NEW.id_biigp,       -- El ID del nuevo reporte-grupo que acabas de crear
        ga.id_user,         -- El ID del usuario que ya pertenece a este grupo
        1                   -- Estado activo
    FROM "bi_i"."bii_group_assigned" ga
    -- Unimos con la tabla de grupos para encontrar a los usuarios del MISMO grupo padre
    JOIN "bi_i"."bii_group" bg ON ga.id_biigp = bg.id_biigp
    WHERE bg.id_biigprpt = NEW.id_biigprpt  -- Filtramos por el ID del grupo padre del nuevo registro
      AND ga.state = 1                      -- Solo usuarios activos
      AND bg.state = 1
    GROUP BY ga.id_user;                    -- Agrupamos para evitar duplicados si un usuario tiene múltiples entradas

    RETURN NEW;
END;
$$;


ALTER FUNCTION bi_i.fn_propagate_new_report_to_users() OWNER TO ronald;

--
-- Name: sp_assign_user_to_full_group(bigint, bigint); Type: FUNCTION; Schema: bi_i; Owner: ronald
--

CREATE FUNCTION bi_i.sp_assign_user_to_full_group(p_id_user bigint, p_id_biigprpt bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT 
        bg.id_biigp,
        p_id_user,
        1
    FROM "bi_i"."bii_group" bg
    WHERE bg.id_biigprpt = p_id_biigprpt
      AND bg.state = 1
    -- El siguiente bloque evita duplicados si el usuario ya tenía algunos asignados
    AND NOT EXISTS (
        SELECT 1 
        FROM "bi_i"."bii_group_assigned" existing 
        WHERE existing.id_biigp = bg.id_biigp 
          AND existing.id_user = p_id_user
    );
END;
$$;


ALTER FUNCTION bi_i.sp_assign_user_to_full_group(p_id_user bigint, p_id_biigprpt bigint) OWNER TO ronald;

--
-- Name: authenticate_and_find_sede(character varying, text, character varying); Type: FUNCTION; Schema: credentials; Owner: ronald
--

CREATE FUNCTION credentials.authenticate_and_find_sede(p_username character varying, p_password text, p_request_ip character varying) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'credentials', 'public'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_password_hash TEXT;
    v_user_state SMALLINT;
    v_fingerprint BOOLEAN;
    v_sedes_encontradas JSON;
    v_cantidad_sedes INT;
BEGIN
    -- PASO 1: Validar credenciales básicas del usuario.
    SELECT id_user, password_hash, state, fingerprint
    INTO v_user_id, v_password_hash, v_user_state, v_fingerprint
    FROM credentials.credentials
    WHERE username = p_username;

    IF NOT FOUND OR v_password_hash IS DISTINCT FROM crypt(p_password, v_password_hash) OR v_user_state <> 1 THEN
        RETURN json_build_object('status', 'INVALID_CREDENTIALS');
    END IF;

    -- PASO 2: Buscar todas las sedes a las que el usuario tiene acceso DESDE LA IP DADA.
    WITH possible_sedes AS (
        SELECT h.id_company, h.id_hdqts, h.name as headquarters_name, c.name as company_name
        FROM sites.ip_company ipc
        JOIN sites.headquarters h ON ipc.id_hdqts = h.id_hdqts
        JOIN sites.company c ON h.id_company = c.id_company
        WHERE ipc.ip = p_request_ip AND NOT c.omit_ip
        UNION
        SELECT h.id_company, h.id_hdqts, h.name as headquarters_name, c.name as company_name
        FROM sites.ip_remote_access ipr
        JOIN sites.headquarters h ON ipr.id_hdqts = h.id_hdqts
        JOIN sites.company c ON h.id_company = c.id_company
        WHERE ipr.ip = p_request_ip AND ipr.id_user = v_user_id AND NOT c.omit_ip
    )
    SELECT json_agg(sedes.*), count(*)
    INTO v_sedes_encontradas, v_cantidad_sedes
    FROM (
        SELECT ps.id_company, ps.id_hdqts, ps.headquarters_name, ps.company_name
        FROM possible_sedes ps
        JOIN sites.access_site sa ON ps.id_hdqts = sa.id_hdqts
        WHERE sa.id_user = v_user_id
    ) as sedes;

    -- PASO 3: Devolver el resultado según la cantidad de sedes encontradas.
    IF v_cantidad_sedes = 0 THEN
        RETURN json_build_object('status', 'ACCESS_DENIED');
    ELSIF v_cantidad_sedes = 1 THEN
        RETURN json_build_object(
            'status', 'AUTHENTICATION_SUCCESS',
            'user_info', json_build_object(
                'id_user', v_user_id,
                'id_company', (v_sedes_encontradas->0->>'id_company')::BIGINT,
                'id_hdqts', (v_sedes_encontradas->0->>'id_hdqts')::BIGINT,
                'fingerprint', v_fingerprint
            )
        );
    ELSE
        RETURN json_build_object(
            'status', 'AMBIGUOUS_SEDE_ACCESS',
            'possible_sedes', v_sedes_encontradas
        );
    END IF;

END;
$$;


ALTER FUNCTION credentials.authenticate_and_find_sede(p_username character varying, p_password text, p_request_ip character varying) OWNER TO ronald;

--
-- Name: authenticate_user(character varying, text, bigint, bigint, character varying); Type: FUNCTION; Schema: credentials; Owner: ronald
--

CREATE FUNCTION credentials.authenticate_user(p_username character varying, p_password text, p_id_company bigint, p_id_hdqts bigint, p_request_ip character varying) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'credentials', 'public'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_password_hash TEXT;
    v_user_state SMALLINT;
    v_fingerprint BOOLEAN;
    v_is_sede_valid BOOLEAN;
    v_is_associated_with_sede BOOLEAN;
    v_is_ip_authorized BOOLEAN;
    v_company_omits_ip BOOLEAN;
BEGIN
    -- PASO 1: Validar credenciales del usuario (usuario, contraseña, estado y obtener fingerprint)
    SELECT id_user, password_hash, state, fingerprint
    INTO v_user_id, v_password_hash, v_user_state, v_fingerprint
    FROM credentials.credentials
    WHERE username = p_username;

    -- Si no se encuentra el usuario o la contraseña no coincide (usando bcrypt) o está inactivo
    IF NOT FOUND OR v_password_hash IS DISTINCT FROM crypt(p_password, v_password_hash) OR v_user_state <> 1 THEN
        RETURN json_build_object('status', 'INVALID_CREDENTIALS', 'id_user', NULL, 'fingerprint', NULL);
    END IF;

    -- PASO 2: Validar que la sede pertenezca a la compañía especificada.
    SELECT EXISTS (
        SELECT 1
        FROM sites.headquarters h
        WHERE h.id_hdqts = p_id_hdqts AND h.id_company = p_id_company
    )
    INTO v_is_sede_valid;

    IF NOT v_is_sede_valid THEN
        RETURN json_build_object('status', 'SEDE_DOES_NOT_BELONG_TO_COMPANY', 'id_user', NULL, 'fingerprint', NULL);
    END IF;

    -- PASO 3: Verificar que el usuario tenga algún permiso de acceso para la sede indicada.
    SELECT EXISTS (
        SELECT 1
        FROM sites.access_site sa
        WHERE sa.id_user = v_user_id AND sa.id_hdqts = p_id_hdqts
    )
    INTO v_is_associated_with_sede;

    IF NOT v_is_associated_with_sede THEN
        RETURN json_build_object('status', 'USER_NOT_AUTHORIZED_FOR_SEDE', 'id_user', NULL, 'fingerprint', NULL);
    END IF;

    -- PASO 4: Validar la dirección IP de origen.
    SELECT c.omit_ip
    INTO v_company_omits_ip
    FROM sites.company c
    WHERE c.id_company = p_id_company;

    IF NOT v_company_omits_ip THEN
        SELECT EXISTS (
            SELECT 1 FROM sites.ip_company ipc WHERE ipc.id_hdqts = p_id_hdqts AND ipc.ip = p_request_ip
            UNION ALL
            SELECT 1 FROM sites.ip_remote_access ipr WHERE ipr.id_hdqts = p_id_hdqts AND ipr.id_user = v_user_id AND ipr.ip = p_request_ip
        )
        INTO v_is_ip_authorized;

        IF NOT v_is_ip_authorized THEN
            RETURN json_build_object('status', 'IP_NOT_AUTHORIZED', 'id_user', NULL, 'fingerprint', NULL);
        END IF;
    END IF;
    
    RETURN json_build_object('status', 'AUTHENTICATION_SUCCESS', 'id_user', v_user_id, 'fingerprint', v_fingerprint);
END;
$$;


ALTER FUNCTION credentials.authenticate_user(p_username character varying, p_password text, p_id_company bigint, p_id_hdqts bigint, p_request_ip character varying) OWNER TO ronald;

--
-- Name: fn_proximo_cumple(date); Type: FUNCTION; Schema: credentials; Owner: ronald
--

CREATE FUNCTION credentials.fn_proximo_cumple(fecha_nacimiento date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  cumple_este_ano DATE;
BEGIN
  -- Construye la fecha de cumpleaños para el año actual
  cumple_este_ano := make_date(
    EXTRACT(YEAR FROM current_date)::int,
    EXTRACT(MONTH FROM fecha_nacimiento)::int,
    EXTRACT(DAY FROM fecha_nacimiento)::int
  );

  -- Si ya pasó, devuelve la fecha del próximo año; si no, la de este año.
  IF cumple_este_ano < current_date THEN
    RETURN cumple_este_ano + INTERVAL '1 year';
  ELSE
    RETURN cumple_este_ano;
  END IF;
END;
$$;


ALTER FUNCTION credentials.fn_proximo_cumple(fecha_nacimiento date) OWNER TO ronald;

--
-- Name: smart_login(character varying, text, bigint, bigint, character varying); Type: FUNCTION; Schema: credentials; Owner: ronald
--

CREATE FUNCTION credentials.smart_login(p_username character varying, p_password text, p_id_company bigint DEFAULT NULL::bigint, p_id_hdqts bigint DEFAULT NULL::bigint, p_request_ip character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'credentials', 'public'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_password_hash TEXT;
    v_user_state SMALLINT;
    v_fingerprint BOOLEAN;
    
    v_is_sede_valid BOOLEAN;
    v_is_associated_with_sede BOOLEAN;
    v_is_ip_authorized BOOLEAN;
    v_company_omits_ip BOOLEAN;
    
    v_sedes_encontradas JSON;
    v_cantidad_sedes INT;
BEGIN
    -- 1. Validar credenciales
    SELECT id_user, password_hash, state, fingerprint
    INTO v_user_id, v_password_hash, v_user_state, v_fingerprint
    FROM credentials.credentials
    WHERE username = p_username;

    IF NOT FOUND 
       OR v_password_hash IS DISTINCT FROM crypt(p_password, v_password_hash) 
       OR v_user_state <> 1 THEN
        RETURN json_build_object('status', 'INVALID_CREDENTIALS');
    END IF;

    -- 2. FLUJO EXPLÍCITO
    IF COALESCE(p_id_company, 0) > 0 AND COALESCE(p_id_hdqts, 0) > 0 THEN
        
        SELECT EXISTS (
            SELECT 1 FROM sites.headquarters h 
            WHERE h.id_hdqts = p_id_hdqts AND h.id_company = p_id_company
        ) INTO v_is_sede_valid;

        IF NOT v_is_sede_valid THEN
            RETURN json_build_object('status', 'SEDE_DOES_NOT_BELONG_TO_COMPANY');
        END IF;

        SELECT EXISTS (
            SELECT 1 FROM sites.access_site sa 
            WHERE sa.id_user = v_user_id AND sa.id_hdqts = p_id_hdqts
        ) INTO v_is_associated_with_sede;

        IF NOT v_is_associated_with_sede THEN
            RETURN json_build_object('status', 'USER_NOT_AUTHORIZED_FOR_SEDE');
        END IF;

        SELECT c.omit_ip INTO v_company_omits_ip
        FROM sites.company c 
        WHERE c.id_company = p_id_company;

        IF NOT COALESCE(v_company_omits_ip, FALSE) THEN
            SELECT EXISTS (
                SELECT 1 FROM sites.ip_company ipc 
                WHERE ipc.id_hdqts = p_id_hdqts AND ipc.ip = p_request_ip
                UNION ALL
                SELECT 1 FROM sites.ip_remote_access ipr 
                WHERE ipr.id_hdqts = p_id_hdqts 
                  AND ipr.id_user = v_user_id 
                  AND ipr.ip = p_request_ip
            ) INTO v_is_ip_authorized;

            IF NOT v_is_ip_authorized THEN
                RETURN json_build_object('status', 'IP_NOT_AUTHORIZED');
            END IF;
        END IF;

        RETURN json_build_object(
            'status', 'AUTHENTICATION_SUCCESS',
            'user_info', json_build_object(
                'id_user', v_user_id,
                'id_company', p_id_company,
                'id_hdqts', p_id_hdqts,
                'fingerprint', v_fingerprint
            )
        );

    ELSE
        -- 🔥 FLUJO INTELIGENTE AVANZADO
        WITH ip_validas AS (
            SELECT ipc.ip
            FROM sites.ip_company ipc
            WHERE ipc.ip = p_request_ip

            UNION

            SELECT ipr.ip
            FROM sites.ip_remote_access ipr
            WHERE ipr.ip = p_request_ip
              AND ipr.id_user = v_user_id
        ),
        sedes_por_ip AS (
            -- Todas las sedes que usan esa IP
            SELECT DISTINCT h.id_company, h.id_hdqts, h.name AS headquarters_name, c.name AS company_name
            FROM ip_validas iv
            JOIN sites.ip_company ipc ON ipc.ip = iv.ip
            JOIN sites.headquarters h ON ipc.id_hdqts = h.id_hdqts
            JOIN sites.company c ON h.id_company = c.id_company
        ),
        sedes_con_acceso AS (
            -- Filtrar por acceso del usuario
            SELECT sp.*
            FROM sedes_por_ip sp
            JOIN sites.access_site sa ON sp.id_hdqts = sa.id_hdqts
            WHERE sa.id_user = v_user_id
        ),
        sedes_sin_ip AS (
            -- Empresas que omiten IP
            SELECT h.id_company, h.id_hdqts, h.name AS headquarters_name, c.name AS company_name
            FROM sites.access_site sa
            JOIN sites.headquarters h ON sa.id_hdqts = h.id_hdqts
            JOIN sites.company c ON h.id_company = c.id_company
            WHERE sa.id_user = v_user_id
              AND c.omit_ip = TRUE
        ),
        todas_sedes AS (
            SELECT * FROM sedes_con_acceso
            UNION
            SELECT * FROM sedes_sin_ip
        )
        SELECT json_agg(s.*), count(*)
        INTO v_sedes_encontradas, v_cantidad_sedes
        FROM todas_sedes s;

        IF v_cantidad_sedes = 0 THEN
            RETURN json_build_object('status', 'ACCESS_DENIED');

        ELSIF v_cantidad_sedes = 1 THEN
            RETURN json_build_object(
                'status', 'AUTHENTICATION_SUCCESS',
                'user_info', json_build_object(
                    'id_user', v_user_id,
                    'id_company', (v_sedes_encontradas->0->>'id_company')::BIGINT,
                    'id_hdqts', (v_sedes_encontradas->0->>'id_hdqts')::BIGINT,
                    'fingerprint', v_fingerprint
                )
            );

        ELSE
            RETURN json_build_object(
                'status', 'AMBIGUOUS_SEDE_ACCESS',
                'possible_sedes', v_sedes_encontradas
            );
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION credentials.smart_login(p_username character varying, p_password text, p_id_company bigint, p_id_hdqts bigint, p_request_ip character varying) OWNER TO ronald;

--
-- Name: get_user_identity_extended(bigint, bigint); Type: FUNCTION; Schema: identity; Owner: ronald
--

CREATE FUNCTION identity.get_user_identity_extended(p_user_id bigint, p_id_app bigint) RETURNS TABLE(external_id text, auth_token text, last_login timestamp without time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.external_user_id,
        (m.sync_metadata -> 'auth' ->> 'user_token')::TEXT,
        m.last_login_at,
        m.sync_metadata
    FROM identity.user_mappings m
    WHERE m.id_user = p_user_id 
      AND m.id_app = p_id_app
      AND m.is_active = true;
END;
$$;


ALTER FUNCTION identity.get_user_identity_extended(p_user_id bigint, p_id_app bigint) OWNER TO ronald;

--
-- Name: get_user_identity_extended(bigint, character varying); Type: FUNCTION; Schema: identity; Owner: ronald
--

CREATE FUNCTION identity.get_user_identity_extended(p_user_id bigint, p_app_name character varying) RETURNS TABLE(external_id text, auth_token text, last_login timestamp without time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.external_id,
        m.auth_token,
        m.last_login,
        m.metadata
    FROM aplication.aplications a
    CROSS JOIN LATERAL identity.get_user_identity_extended(p_user_id, a.id_app) m
    WHERE a.name_app = p_app_name 
      AND a.state = 1;
END;
$$;


ALTER FUNCTION identity.get_user_identity_extended(p_user_id bigint, p_app_name character varying) OWNER TO ronald;

