-- Name: resolve_ecosystem_user(bigint, text); Type: FUNCTION; Schema: identity; Owner: ronald
--

CREATE FUNCTION identity.resolve_ecosystem_user(p_id_app bigint, p_external_id text) RETURNS bigint
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_user_id BIGINT;
BEGIN
    SELECT m.id_user INTO v_user_id
    FROM identity.user_mappings m
    WHERE m.id_app = p_id_app 
      AND m.external_user_id = p_external_id
      AND m.is_active = true;
    
    RETURN v_user_id;
END;
$$;


