--
-- Name: resolve_ecosystem_user(character varying, text); Type: FUNCTION; Schema: identity; Owner: ronald
--

CREATE FUNCTION identity.resolve_ecosystem_user(p_app_name character varying, p_external_id text) RETURNS bigint
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_user_id BIGINT;
BEGIN
    SELECT m.id_user INTO v_user_id
    FROM identity.user_mappings m
    JOIN aplication.aplications a ON m.id_app = a.id_app
    WHERE a.name_app = p_app_name 
      AND m.external_user_id = p_external_id
      AND m.is_active = true
      AND a.state = 1;
    
    RETURN v_user_id;
END;
$$;


