--
-- Name: upsert_user_photo(bigint, character varying, character varying); Type: FUNCTION; Schema: photograph; Owner: ronald
--

CREATE FUNCTION photograph.upsert_user_photo(p_id_user bigint, p_photo_path character varying, p_photo_type character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id_phus bigint;
    v_default_photo_id bigint;
BEGIN
    -- 1. Asegurarse de que existe una foto por defecto (o tomar la primera disponible)
    SELECT id_dfpht INTO v_default_photo_id FROM photograph.photo_default WHERE state = 1 LIMIT 1;
    IF v_default_photo_id IS NULL THEN
        -- Si no hay fotos por defecto, inserta una placeholder.
        -- ¡IMPORTANTE! Asegúrate de tener al menos un registro en 'photo_default'.
    END IF;

    -- 2. Buscar si ya existe un registro para este usuario
    SELECT id_phus INTO v_id_phus FROM photograph.photos_user WHERE id_user = p_id_user;

    -- 3. Si existe (UPDATE), si no (INSERT)
    IF v_id_phus IS NOT NULL THEN
        -- Ya existe un registro, actualizamos la columna correspondiente
        EXECUTE format(
            'UPDATE photograph.photos_user SET %I = $1, register = CURRENT_TIMESTAMP WHERE id_phus = $2',
            p_photo_type || '_photo_path' -- Construye el nombre de la columna dinámicamente
        ) USING p_photo_path, v_id_phus;
    ELSE
        -- No existe, creamos un nuevo registro
        EXECUTE format(
            'INSERT INTO photograph.photos_user (id_user, id_dfpht, %I) VALUES ($1, $2, $3) RETURNING id_phus',
            p_photo_type || '_photo_path'
        ) USING p_id_user, v_default_photo_id, p_photo_path INTO v_id_phus;
    END IF;

    RETURN v_id_phus;
END;
$_$;


ALTER FUNCTION photograph.upsert_user_photo(p_id_user bigint, p_photo_path character varying, p_photo_type character varying) OWNER TO ronald;

--
-- Name: calcular_descuento_tardanza(integer, integer, integer, date, bigint); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.calcular_descuento_tardanza(p_id_user integer DEFAULT NULL::integer, p_anio integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer, p_mes integer DEFAULT NULL::integer, p_fecha date DEFAULT NULL::date, p_editor_id bigint DEFAULT 213) RETURNS text
    LANGUAGE plpgsql
    AS $$
/*
DESCRIPCION: Función principal para procesar lotes de descuentos por tardanza.
Llama a planilla.procesar_descuento_tardanza para cada registro que cumpla los filtros.

-- ==================================================================
-- MODIFICACIÓN (FIX 5):
-- Se reemplazó toda la lógica LATERAL de horario.
--
-- MOTIVO:
-- La nueva lógica prioriza las "schedule_exceptions" sobre las
-- "schedule_template_entries".
-- Calcula correctamente el primer horario de entrada (para la
-- tardanza) y la jornada laboral total (sumando todos los bloques
-- de trabajo del día, en caso de horario partido).
-- ==================================================================
*/
DECLARE
    rec RECORD;
    processed_count INT := 0;
BEGIN
    FOR rec IN
        -- Consulta registros que potencialmente tienen tardanza
        SELECT
            ar.id_atdreg,
            ar."date"
        FROM attendance.attendance_register ar
        
        -- <<<<<<<<<<<<<<<< INICIO FIX 5: LÓGICA DE HORARIO UNIFICADA (CON EXCEPCIONES) >>>>>>>>>>>>>>>>>>
        LEFT JOIN LATERAL (
            WITH
            -- 1. Buscar una excepción activa para este día
            CTE_Exception AS (
                SELECT id_sch_exc
                FROM planilla.schedule_exceptions se
                WHERE se.id_user = ar.id_user
                  AND se.exception_date = ar."date"
                  AND se.state = TRUE
                LIMIT 1
            ),
            -- 2. Si hay excepción, obtener sus bloques.
            CTE_Exception_Blocks AS (
                SELECT
                    seb.entry_time,
                    seb.exit_time
                FROM planilla.schedule_exception_blocks seb
                JOIN CTE_Exception ce ON seb.id_sch_exc = ce.id_sch_exc
                WHERE seb.state = TRUE
                  AND seb.entry_time IS NOT NULL
                  AND seb.exit_time IS NOT NULL
            ),
            -- 3. Si NO hay excepción (COUNT=0), buscar el horario de plantilla
            CTE_Template_Schedule_Find AS (
                SELECT
                    us.id_sch_tpl,
                    st.schedule_type,
                    us.rotation_anchor_date,
                    (SELECT MAX(ste_inner.identifier_day)
                     FROM planilla.schedule_template_entries ste_inner
                     WHERE ste_inner.id_sch_tpl = us.id_sch_tpl AND ste_inner.state = TRUE) AS cycle_days
                FROM planilla.user_schedules us
                JOIN planilla.schedule_templates st ON us.id_sch_tpl = st.id_sch_tpl
                WHERE us.id_user = ar.id_user
                  AND ar."date" BETWEEN us.start_date AND COALESCE(us.end_date, ar."date")
                  AND us.state = TRUE
                  AND st.state = TRUE
                  AND (SELECT COUNT(*) FROM CTE_Exception) = 0 -- Solo si NO hay excepción
                LIMIT 1
            ),
            CTE_Template_Day AS (
                SELECT
                    id_sch_tpl,
                    CASE
                        WHEN schedule_type = 1 THEN EXTRACT(ISODOW FROM ar."date")::smallint
                        WHEN schedule_type = 2 AND rotation_anchor_date IS NOT NULL AND cycle_days > 0 THEN
                             ( ( (ar."date"::date - rotation_anchor_date::date) % cycle_days + cycle_days ) % cycle_days ) + 1
                        ELSE -1
                    END AS day_to_find
                FROM CTE_Template_Schedule_Find
            ),
            CTE_Template_Blocks AS (
                SELECT
                    ste.entry_time,
                    ste.exit_time
                FROM planilla.schedule_template_entries ste
                JOIN CTE_Template_Day td ON ste.id_sch_tpl = td.id_sch_tpl
                WHERE ste.identifier_day = td.day_to_find
                  AND ste.state = TRUE
                  AND ste.entry_time IS NOT NULL
                  AND ste.exit_time IS NOT NULL
            ),
            -- 4. Combinar los bloques (solo uno de los dos CTEs de bloques tendrá filas)
            CTE_All_Blocks AS (
                SELECT * FROM CTE_Exception_Blocks
                UNION ALL
                SELECT * FROM CTE_Template_Blocks
            )
            -- 5. Calcular la primera entrada y la jornada total
            SELECT
                MIN(entry_time) AS first_entry_time,
                -- SUM(EXTRACT(EPOCH FROM (exit_time - entry_time))) AS total_work_seconds, -- (No se usa en esta función)
                CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS laborable
            FROM CTE_All_Blocks
        ) wkhs(entry_time, laborable) ON TRUE -- 'segundos_laborables' se omite aquí a propósito
        -- <<<<<<<<<<<<<<<< FIN FIX 5 >>>>>>>>>>>>>>>>>>
        
        WHERE wkhs.laborable = 1
          AND ar.entry_time IS NOT NULL -- Debe tener entrada marcada
          AND ar.state = TRUE
          AND (p_id_user IS NULL OR ar.id_user = p_id_user)
          AND (p_fecha IS NULL OR ar."date" = p_fecha)
          AND (p_mes IS NULL OR (EXTRACT(YEAR FROM ar."date") = p_anio AND EXTRACT(MONTH FROM ar."date") = p_mes))
    LOOP
        -- Llamar a la función modular para procesar el descuento
        PERFORM planilla.procesar_descuento_tardanza(rec.id_atdreg, rec."date", p_editor_id);

        processed_count := processed_count + 1;
    END LOOP;

    RETURN 'Proceso de orquestación completado. Se procesaron ' || processed_count || ' registros de tardanza.';
END;
$$;


ALTER FUNCTION planilla.calcular_descuento_tardanza(p_id_user integer, p_anio integer, p_mes integer, p_fecha date, p_editor_id bigint) OWNER TO ronald;

--
-- Name: calcular_sueldo_bruto(numeric, integer, integer, integer); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.calcular_sueldo_bruto(p_ponderado numeric, p_dias_computados integer, p_year integer, p_month integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dias_del_mes INT;
BEGIN
    v_dias_del_mes := EXTRACT(DAY FROM (make_date(p_year, p_month, 1) + interval '1 month' - interval '1 day'));

    IF v_dias_del_mes IS NULL OR v_dias_del_mes = 0 THEN
        RETURN 0.00;
    END IF;

    -- CORRECCIÓN: Usamos ROUND() para forzar el redondeo a 2 decimales.
    RETURN ROUND((p_ponderado / v_dias_del_mes) * p_dias_computados, 2);
END;
$$;


ALTER FUNCTION planilla.calcular_sueldo_bruto(p_ponderado numeric, p_dias_computados integer, p_year integer, p_month integer) OWNER TO ronald;

