COMMENT ON FUNCTION planilla.calcular_sueldo_bruto(p_ponderado numeric, p_dias_computados integer, p_year integer, p_month integer) IS 'Calcula el sueldo bruto en base al ponderado, los días del mes y los días computados.';


--
-- Name: get_bono_fijo(bigint, boolean); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.get_bono_fijo(p_id_user bigint, p_show_details boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_bonus_record RECORD;
    v_result JSONB;
    v_fixed_bonus_id INT := 1; 
BEGIN
    -- Busca el bono asignado para el usuario y el TIPO FIJO específico.
    SELECT
        asgbn.paid,
        asgbn.editor,
        asgbn."comment"
    INTO v_bonus_record
    FROM
        planilla.assigned_bonus AS asgbn
    WHERE
        asgbn.id_user = p_id_user AND asgbn.id_typbon = v_fixed_bonus_id;

    -- La lógica para construir el JSON se mantiene igual.
    IF FOUND THEN
        IF p_show_details THEN
            v_result := jsonb_build_object(
                'paid', v_bonus_record.paid,
                'editor', v_bonus_record.editor,
                'comment', v_bonus_record.comment
            );
        ELSE
            v_result := jsonb_build_object('paid', v_bonus_record.paid);
        END IF;
    ELSE
        v_result := jsonb_build_object(
            'paid', 0.00,
            'editor', NULL,
            'comment', NULL
        );
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION planilla.get_bono_fijo(p_id_user bigint, p_show_details boolean) OWNER TO ronald;

--
-- Name: get_dias_computados(bigint, integer, integer); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.get_dias_computados(p_id_user bigint, p_year integer, p_month integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT planilla.get_dias_laborados(p_id_user, p_year, p_month)
             + planilla.get_dias_no_laborados_remunerados(p_id_user, p_year, p_month)
    );
END;
$$;


ALTER FUNCTION planilla.get_dias_computados(p_id_user bigint, p_year integer, p_month integer) OWNER TO ronald;

--
-- Name: get_dias_laborados(bigint, integer, integer); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.get_dias_laborados(p_id_user bigint, p_year integer, p_month integer) RETURNS integer
    LANGUAGE sql
    AS $$
    SELECT COUNT(*)::INT
    FROM attendance.attendance_control ac
    -- Unimos con la tabla de códigos
    JOIN attendance.attendance_code code ON ac.id_atdcode = code.id_atdcode
    WHERE
        ac.id_user = p_id_user
        AND DATE_TRUNC('month', ac."date") = MAKE_DATE(p_year, p_month, 1)
        -- Leemos la categoría en lugar de la lista 'IN'
        AND code.categoria_planilla = 1;
$$;


