--
-- Name: get_formatted_mother_name(text, text, text, text); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.get_formatted_mother_name(full_name text, p_surname text, m_surname text, case_style text DEFAULT 'Proper'::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
SELECT
    -- 4. Aplica la conversión de mayúsculas/minúsculas
    CASE
        WHEN $4 ILIKE 'Upper' THEN UPPER(combined_name)
        WHEN $4 ILIKE 'Lower' THEN LOWER(combined_name)
        
        -- Por defecto ('Proper'):
        -- ¡FIX V5! Reemplazamos INITCAP() con una implementación manual
        -- que es segura para 'locales' (configuraciones regionales) rotos.
        -- Esto divide la cadena en palabras, capitaliza cada una y las vuelve a unir.
        ELSE (
            SELECT array_to_string(
                ARRAY(
                    SELECT UPPER(SUBSTRING(word, 1, 1)) || SUBSTRING(word, 2)
                    FROM unnest(string_to_array(combined_name, ' ')) AS word
                ),
            ' '
            )
        )
    END AS final_name
FROM (
    -- Esta subconsulta de V4 es CORRECTA.
    -- Produce 'marjorie farfán' y 'ronald de la cruz'
    SELECT
        -- 3. Combina el primer nombre y el apellido seleccionado
        (
            -- 1. Extrae el Primer Nombre (forzado a minúscula)
            SPLIT_PART(
                LOWER(TRANSLATE(TRIM(COALESCE($1, '')), 'ÁÉÍÓÚÑ', 'áéíóúñ')),
                ' ', 1
            ) || ' ' ||
            -- 2. Lógica de selección del Apellido (forzado a minúscula)
            COALESCE(
                CASE
                    WHEN TRIM(COALESCE($2, '')) NOT IN ('-', '') THEN
                        LOWER(TRANSLATE($2, 'ÁÉÍÓÚÑ', 'áéíóúñ'))
                    ELSE NULL
                END,
                LOWER(TRANSLATE($3, 'ÁÉÍÓÚÑ', 'áéíóúñ'))
            )
        ) AS combined_name
) AS subquery;
$_$;


ALTER FUNCTION planilla.get_formatted_mother_name(full_name text, p_surname text, m_surname text, case_style text) OWNER TO ronald;

--
-- Name: procesar_descuento_tardanza(bigint, date, bigint); Type: FUNCTION; Schema: planilla; Owner: ronald
--

CREATE FUNCTION planilla.procesar_descuento_tardanza(p_id_atdreg bigint, p_date date, p_editor_id bigint DEFAULT 213) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'planilla, attendance, public'
    AS $$
/*
DESCRIPCION: Calcula y aplica el descuento por tardanza.
-- FIX COMPLETO:
-- 1. Sueldo: Busca en basic_remuneration vigente (sin depender de payments).
-- 2. Contrato: Busca contrato vigente en la FECHA EXACTA (soporta ingresos a mitad de mes).
-- 3. Seguridad: Search_path fijado.
*/
DECLARE
    v_id_atdctr BIGINT;
    v_id_atddisc BIGINT;
    v_tardanza_interval INTERVAL;
    v_descuento_calculado NUMERIC(5, 2);
    v_id_atdtypdisc BIGINT;
    v_id_user BIGINT;
    
    -- Variables para log/debug
    v_programada TIME;
    v_real TIME;
    v_sueldo NUMERIC(10, 2);
    v_job_time INTERVAL;
    v_obsolete_discount_ids BIGINT[];
BEGIN
    -- 0. Validar Tipo de Descuento
    SELECT id_atdtypdisc INTO v_id_atdtypdisc
    FROM attendance.types_attendance_discounts
    WHERE name = 'TARDANZA' AND state = TRUE LIMIT 1;

    IF v_id_atdtypdisc IS NULL THEN
        RAISE WARNING 'Tipo de descuento TARDANZA no encontrado.';
        RETURN NULL;
    END IF;

    -- 1. CTE Principal de Cálculo
    WITH registro_descuento AS (
        SELECT
            ar.id_user,
            wkhs.entry_time AS entry_prog,
            ar.entry_time AS entry_real,
            -- Cálculo de tiempo
            GREATEST('0 seconds'::interval, ar.entry_time - wkhs.entry_time) AS tardanza_interval,
            -- Cálculo de jornada (para prorrateo)
            NULLIF(EXTRACT(EPOCH FROM COALESCE(mdty.time_working::interval, (wkhs.exit_time - wkhs.entry_time))), 0) AS segundos_laborables,
            COALESCE(mdty.time_working::interval, (wkhs.exit_time - wkhs.entry_time)) AS job_duration_interval,
            
            -- SUELDO: Usamos COALESCE para evitar error matemático si es NULL
            COALESCE(bsrm.amount, 0) AS sueldo_base

        FROM attendance.attendance_register ar
        
        -- A) LÓGICA DE HORARIO
        LEFT JOIN LATERAL (
            WITH ActiveSchedule AS (
                SELECT us.id_sch_tpl, st.schedule_type, us.rotation_anchor_date,
                    (SELECT MAX(identifier_day) FROM planilla.schedule_template_entries WHERE id_sch_tpl = us.id_sch_tpl AND state = TRUE) AS cycle_days
                FROM planilla.user_schedules us
                JOIN planilla.schedule_templates st ON us.id_sch_tpl = st.id_sch_tpl
                WHERE us.id_user = ar.id_user
                  AND ar."date" BETWEEN us.start_date AND COALESCE(us.end_date, ar."date")
                  AND us.state = TRUE AND st.state = TRUE
                LIMIT 1
            ),
            TargetDay AS (
                SELECT id_sch_tpl,
                    CASE
                        WHEN schedule_type = 1 THEN EXTRACT(ISODOW FROM ar."date")::smallint
                        WHEN schedule_type = 2 THEN (((ar."date"::date - rotation_anchor_date::date) % cycle_days + cycle_days) % cycle_days) + 1
                        ELSE -1
                    END AS day_to_find
                FROM ActiveSchedule
            )
            SELECT ste.entry_time, ste.exit_time, 1 AS laborable
            FROM planilla.schedule_template_entries ste
            JOIN TargetDay td ON ste.id_sch_tpl = td.id_sch_tpl
            WHERE ste.identifier_day = td.day_to_find AND ste.state = TRUE
              AND ste.entry_time IS NOT NULL AND ste.exit_time IS NOT NULL
            ORDER BY ste.entry_time ASC LIMIT 1
        ) wkhs(entry_time, exit_time, laborable) ON TRUE
        
        -- B) LÓGICA DE CONTRATO (CORREGIDA PARA MITAD DE MES)
        LEFT JOIN LATERAL (
            SELECT id_contract, id_typmod 
            FROM planilla.contract c
            WHERE c.id_user = ar.id_user 
              -- Valida que la fecha de la falta esté dentro del rango del contrato
              AND p_date >= c.contract_ini 
              AND p_date <= COALESCE(c.contract_end, '2999-12-31'::date)
            ORDER BY c.contract_ini DESC 
            LIMIT 1
        ) ctc ON TRUE
        
        LEFT JOIN planilla.modality_type mdty ON ctc.id_typmod = mdty.id_typmod

        -- C) LÓGICA DE SUELDO (VIGENTE A LA FECHA)
        LEFT JOIN LATERAL (
            SELECT amount 
            FROM planilla.basic_remuneration 
            WHERE id_user = ar.id_user 
              AND state = 1 
              AND "date" <= p_date 
            ORDER BY "date" DESC, id_bscrem DESC
            LIMIT 1
        ) bsrm ON TRUE

        WHERE ar.id_atdreg = p_id_atdreg
          AND ar."date" = p_date
          AND wkhs.laborable = 1
          AND ar.state = TRUE
    )
    SELECT
        rd.entry_prog, rd.entry_real, rd.sueldo_base, rd.job_duration_interval, rd.tardanza_interval,
        ROUND((EXTRACT(EPOCH FROM rd.tardanza_interval) / NULLIF(rd.segundos_laborables, 0)) * (rd.sueldo_base / 30.0), 2)
    INTO
        v_programada, v_real, v_sueldo, v_job_time, v_tardanza_interval, v_descuento_calculado
    FROM registro_descuento rd;

    -- LOGGING
    RAISE NOTICE '--- CALCULO TARDANZA % ---', p_date;
    RAISE NOTICE 'Sueldo Base: % | Descuento Calc: %', v_sueldo, v_descuento_calculado;
    
    -- 2. Validar Tardanza > 1 minuto
    IF v_tardanza_interval >= '00:01:00'::interval THEN
        
        SELECT id_atdctr INTO v_id_atdctr
        FROM attendance.attendance_control
        WHERE id_atdreg = p_id_atdreg AND "date" = p_date AND state = TRUE LIMIT 1;

        IF NOT FOUND THEN
            RAISE WARNING 'Falta attendance_control para id_atdreg %', p_id_atdreg;
            RETURN NULL;
        END IF;

        -- Upsert Descuento
        UPDATE attendance.attendance_discount
        SET discount = v_descuento_calculado, "time" = v_tardanza_interval, editor = p_editor_id, date_register = NOW()
        WHERE id_atdreg = p_id_atdreg AND "date" = p_date AND id_atdtypdisc = v_id_atdtypdisc
        RETURNING id_atddisc INTO v_id_atddisc;

        IF NOT FOUND THEN
            RETURNING id_atddisc INTO v_id_atddisc;
        END IF;

        VALUES (v_id_atddisc, v_id_atdctr, p_date)
        ON CONFLICT DO NOTHING;

        RETURN v_id_atddisc;

    ELSE
        -- Borrar descuentos previos
        SELECT array_agg(id_atddisc) INTO v_obsolete_discount_ids
        FROM attendance.attendance_discount 
        WHERE id_atdtypdisc = v_id_atdtypdisc AND date = p_date AND id_atdreg = p_id_atdreg AND state = TRUE;
        
        IF v_obsolete_discount_ids IS NOT NULL THEN
            DELETE FROM attendance.attendance_control_discount WHERE id_atddisc = ANY(v_obsolete_discount_ids);
            DELETE FROM attendance.attendance_discount WHERE id_atddisc = ANY(v_obsolete_discount_ids);
        END IF;
        
        RETURN NULL;
    END IF;

EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error %', SQLERRM;
END;
$$;


ALTER FUNCTION planilla.procesar_descuento_tardanza(p_id_atdreg bigint, p_date date, p_editor_id bigint) OWNER TO ronald;

--
-- Name: handle_candidate_follow_up(bigint, date, bigint, bigint, boolean, boolean, character varying, bigint, integer, integer); Type: FUNCTION; Schema: rrhh; Owner: ronald
--

CREATE FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo integer, p_id_cmpg integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_date_rhrtdt DATE;
    v_new_state INT;
BEGIN
    -- Obtener la fecha de partición internamente para asegurar la consistencia
    SELECT date INTO v_date_rhrtdt
    FROM rrhh.recruitment_data
    WHERE id_rhrtdt = p_id_rhrtdt
    ORDER BY date DESC
    LIMIT 1;

    IF v_date_rhrtdt IS NULL THEN
        RAISE EXCEPTION 'No se encontró el registro de reclutamiento con ID %', p_id_rhrtdt;
    END IF;

    -- 1. Insertar o actualizar la asignación de entrevista
    IF p_date IS NOT NULL AND p_id_rhintrg IS NOT NULL THEN
        VALUES (p_id_rhrtdt, v_date_rhrtdt, p_date, p_id_rhintrg, p_interviewer, TRUE)
        ON CONFLICT (id_rhrtdt, date_recruitment_data) WHERE state = TRUE
        DO UPDATE SET
            date = EXCLUDED.date,
            id_rhintrg = EXCLUDED.id_rhintrg,
            interviewer = EXCLUDED.interviewer;
    END IF;

    -- 2. Insertar interés del candidato
    VALUES (p_id_rhrtdt, v_date_rhrtdt, p_availability, p_interest, COALESCE(p_reason, ''), CURRENT_DATE);

    -- 3. Actualizar rrhh_recruitment_data si se proporcionaron nuevos valores
    UPDATE rrhh.recruitment_data
    SET
        id_rhnmps = COALESCE(p_puesto, id_rhnmps),
        id_ptflo  = COALESCE(p_id_ptflo, id_ptflo),
        id_cmpg   = COALESCE(p_id_cmpg, id_cmpg),
        editor    = p_interviewer
    WHERE id_rhrtdt = p_id_rhrtdt AND date = v_date_rhrtdt;

    -- 4. Determinar el nuevo estado y actualizar rrhh.postulant_tracking
    v_new_state := NULL;
    IF p_availability = TRUE AND p_interest = TRUE AND p_date IS NOT NULL THEN
        v_new_state := 1; -- Confirmado
    ELSIF p_interest = FALSE THEN
        v_new_state := 3; -- Denegado/No interesado
    END IF;

    IF v_new_state IS NOT NULL THEN
        -- Desactivar el estado anterior (id_rhmtst = 2)
        UPDATE rrhh.postulant_tracking
        SET state = FALSE
        WHERE id_rhrtdt = p_id_rhrtdt AND date_recruitment_data = v_date_rhrtdt AND id_rhmtst = 2;
        
        -- Insertar el nuevo estado
        VALUES (p_id_rhrtdt, v_date_rhrtdt, v_new_state);
    END IF;

END;
$$;


ALTER FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo integer, p_id_cmpg integer) OWNER TO ronald;

--
-- Name: handle_candidate_follow_up(bigint, date, bigint, bigint, boolean, boolean, character varying, bigint, bigint, bigint); Type: FUNCTION; Schema: rrhh; Owner: ronald
--

CREATE FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo bigint, p_id_cmpg bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_date_rhrtdt DATE;
    v_new_state INT;
    v_existing_interview_id BIGINT;
BEGIN
    -- Obtener la fecha de partición internamente para asegurar la consistencia
    SELECT date INTO v_date_rhrtdt
    FROM rrhh.recruitment_data
    WHERE id_rhrtdt = p_id_rhrtdt
    ORDER BY date DESC
    LIMIT 1;

    IF v_date_rhrtdt IS NULL THEN
        RAISE EXCEPTION 'No se encontró el registro de reclutamiento con ID %', p_id_rhrtdt;
    END IF;

    -- 1. Lógica de "UPSERT" manual para la asignación de entrevista
    IF p_date IS NOT NULL AND p_id_rhintrg IS NOT NULL THEN
        -- Buscar si ya existe una entrevista activa para este candidato
        SELECT id_rhintasg INTO v_existing_interview_id
        FROM rrhh.interview_assigned
        WHERE id_rhrtdt = p_id_rhrtdt AND state = TRUE
        LIMIT 1;

        IF v_existing_interview_id IS NOT NULL THEN
            -- Si existe, se actualiza
            UPDATE rrhh.interview_assigned
            SET
                date = p_date,
                id_rhintrg = p_id_rhintrg,
                interviewer = p_interviewer
            WHERE id_rhintasg = v_existing_interview_id;
        ELSE
            -- Si no existe, se inserta una nueva
            VALUES (p_id_rhrtdt, v_date_rhrtdt, p_date, p_id_rhintrg, p_interviewer, TRUE);
        END IF;
    END IF;

    -- 2. Insertar interés del candidato
    VALUES (p_id_rhrtdt, v_date_rhrtdt, p_availability, p_interest, COALESCE(p_reason, ''), CURRENT_DATE);

    -- 3. Actualizar rrhh_recruitment_data si se proporcionaron nuevos valores
    UPDATE rrhh.recruitment_data
    SET
        id_rhnmps = COALESCE(p_puesto, id_rhnmps),
        id_ptflo  = COALESCE(p_id_ptflo, id_ptflo),
        id_cmpg   = COALESCE(p_id_cmpg, id_cmpg),
        editor    = p_interviewer
    WHERE id_rhrtdt = p_id_rhrtdt AND date = v_date_rhrtdt;

    -- 4. Determinar el nuevo estado y actualizar rrhh.postulant_tracking
    v_new_state := NULL;
    IF p_availability = TRUE AND p_interest = TRUE AND p_date IS NOT NULL THEN
        v_new_state := 1; -- Confirmado
    ELSIF p_interest = FALSE THEN
        v_new_state := 3; -- Denegado/No interesado
    END IF;

    IF v_new_state IS NOT NULL THEN
        -- Desactivar el estado anterior (id_rhmtst = 2)
        UPDATE rrhh.postulant_tracking
        SET state = FALSE
        WHERE id_rhrtdt = p_id_rhrtdt AND date_recruitment_data = v_date_rhrtdt AND id_rhmtst = 2;
        
        -- Insertar el nuevo estado
        VALUES (p_id_rhrtdt, v_date_rhrtdt, v_new_state);
    END IF;

END;
$$;


ALTER FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo bigint, p_id_cmpg bigint) OWNER TO ronald;

--
-- Name: handle_candidate_follow_up(bigint, date, date, bigint, bigint, boolean, boolean, character varying, bigint, integer, integer); Type: FUNCTION; Schema: rrhh; Owner: ronald
--

CREATE FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date_rhrtdt date, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo integer, p_id_cmpg integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_state INT;
BEGIN
    -- 1. Insertar o actualizar la asignación de entrevista
    IF p_date IS NOT NULL AND p_id_rhintrg IS NOT NULL THEN
        VALUES (p_id_rhrtdt, p_date_rhrtdt, p_date, p_id_rhintrg, p_interviewer, TRUE)
        ON CONFLICT (id_rhrtdt, date_recruitment_data) WHERE state = TRUE
        DO UPDATE SET
            date = EXCLUDED.date,
            id_rhintrg = EXCLUDED.id_rhintrg,
            interviewer = EXCLUDED.interviewer;
    END IF;

    -- 2. Insertar interés del candidato
    VALUES (p_id_rhrtdt, p_date_rhrtdt, p_availability, p_interest, COALESCE(p_reason, ''), CURRENT_DATE);

    -- 3. Actualizar rrhh_recruitment_data si se proporcionaron nuevos valores
    UPDATE rrhh.recruitment_data
    SET
        id_rhnmps = COALESCE(p_puesto, id_rhnmps),
        id_ptflo  = COALESCE(p_id_ptflo, id_ptflo),
        id_cmpg   = COALESCE(p_id_cmpg, id_cmpg),
        editor    = p_interviewer
    WHERE id_rhrtdt = p_id_rhrtdt AND date = p_date_rhrtdt;

    -- 4. Determinar el nuevo estado y actualizar rrhh.postulant_tracking
    v_new_state := NULL;
    IF p_availability = TRUE AND p_interest = TRUE AND p_date IS NOT NULL THEN
        v_new_state := 1; -- Confirmado
    ELSIF p_interest = FALSE THEN
        v_new_state := 3; -- Denegado/No interesado
    END IF;

    IF v_new_state IS NOT NULL THEN
        -- Desactivar el estado anterior (id_rhmtst = 2)
        UPDATE rrhh.postulant_tracking
        SET state = FALSE
        WHERE id_rhrtdt = p_id_rhrtdt AND date_recruitment_data = p_date_rhrtdt AND id_rhmtst = 2;
        
        -- Insertar el nuevo estado
        VALUES (p_id_rhrtdt, p_date_rhrtdt, v_new_state);
    END IF;

END;
$$;


ALTER FUNCTION rrhh.handle_candidate_follow_up(p_id_rhrtdt bigint, p_date_rhrtdt date, p_date date, p_id_rhintrg bigint, p_interviewer bigint, p_availability boolean, p_interest boolean, p_reason character varying, p_puesto bigint, p_id_ptflo integer, p_id_cmpg integer) OWNER TO ronald;

--
-- Name: insert_contactacion(bigint, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, integer, integer, integer, bigint, text); Type: FUNCTION; Schema: rrhh; Owner: ronald
--

CREATE FUNCTION rrhh.insert_contactacion(p_recruiter_id bigint, p_id_rhrtmd integer, p_name character varying, p_paternal_surname character varying, p_maternal_surname character varying, p_email character varying, p_nick character varying, p_id_tydoc integer, p_document_number character varying, p_mobile character varying, p_id_ptflo integer, p_id_cmpg integer, p_id_hdqts integer, p_to_referral_id bigint, p_comment text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_is_new BOOLEAN;
    v_rhrtdt_id BIGINT;
    v_current_date DATE := CURRENT_DATE;
    v_event_type_id BIGINT; -- Variable para el tipo de evento de trayectoria
BEGIN
    -- Búsqueda dinámica del ID del tipo de evento de trayectoria ('CONTACTACION')
    SELECT id_evty INTO v_event_type_id
    FROM trajectory.event_types
    WHERE name = 'CONTACTACION' AND state = TRUE;
    
    IF v_event_type_id IS NULL THEN
        RAISE EXCEPTION 'No se encontró un tipo de evento llamado "CONTACTACION" que esté activo en la tabla trajectory.event_types.';
    END IF;

    -- 1. Validación de duplicados
    IF EXISTS (
        SELECT 1 FROM rrhh.recruitment_data
        WHERE
            (rrhh.recruitment_data.email = p_email AND p_email IS NOT NULL AND TRIM(p_email) <> '') OR
            (rrhh.recruitment_data.document_number = p_document_number AND p_document_number IS NOT NULL AND TRIM(p_document_number) <> '') OR
            (rrhh.recruitment_data.mobile = p_mobile AND p_mobile IS NOT NULL AND TRIM(p_mobile) <> '')
    ) THEN
        v_is_new := FALSE;
    ELSE
        v_is_new := TRUE;
    END IF;

    -- 2. Insertar en la tabla principal de reclutamiento (rrhh.recruitment_data)
        recruiter, date, id_rhrtmd, name, paternal_surname,
        maternal_surname, email, nick, id_tydoc,
        document_number, mobile, id_ptflo, id_cmpg, new, id_hdqts, register, state
    )
    VALUES (
        p_recruiter_id, v_current_date, p_id_rhrtmd, p_name, p_paternal_surname,
        p_maternal_surname, p_email, p_nick, p_id_tydoc,
        p_document_number, p_mobile, p_id_ptflo, p_id_cmpg, v_is_new, p_id_hdqts, CURRENT_TIMESTAMP, TRUE
    )
    RETURNING id_rhrtdt INTO v_rhrtdt_id;

    -- 3. Insertar el estado inicial 'PENDIENTE' (ID 2)
    -- Este es el estado inicial del postulante en su seguimiento.
    VALUES (v_rhrtdt_id, v_current_date, 2, CURRENT_TIMESTAMP, TRUE);
    
    -- 4. Insertar en la tabla de referidos si el medio de reclutamiento es 9 o 11
    IF p_id_rhrtmd IN (9, 11) AND p_to_referral_id IS NOT NULL THEN
            id_referrer_user, referred_name, referral_date, is_rehire, referral_status, state
        )
        VALUES (
            p_to_referral_id,
            TRIM(CONCAT(p_name, ' ', p_paternal_surname, ' ', p_maternal_surname)),
            v_current_date,
            FALSE,
            'PENDING',
            TRUE
        );
    END IF;

    -- 5. Insertar comentario si se proporcionó uno.
    IF p_comment IS NOT NULL AND TRIM(p_comment) <> '' THEN
        VALUES (v_rhrtdt_id, v_current_date, p_comment, TRUE);
    END IF;
    
    -- 6. *** CORRECCIÓN FINAL: Insertar el evento en la trayectoria para el NUEVO POSTULANTE ***
    -- Se registra el primer evento en la historia del postulante, que aún no tiene id_user.
        id_user, id_evty, event_date, related_schema, related_table, related_id, state
    )
    VALUES (
        NULL, -- El id_user es nulo porque el postulante aún no es un usuario formal.
        v_event_type_id, -- ID dinámico para 'CONTACTACION' de trajectory.event_types
        v_current_date,
        'rrhh',
        'recruitment_data',
        v_rhrtdt_id, -- El evento se relaciona con el registro de reclutamiento recién creado.
        TRUE
    );

    -- 7. Retornar el ID del nuevo registro principal
    RETURN v_rhrtdt_id;

END;
$$;


ALTER FUNCTION rrhh.insert_contactacion(p_recruiter_id bigint, p_id_rhrtmd integer, p_name character varying, p_paternal_surname character varying, p_maternal_surname character varying, p_email character varying, p_nick character varying, p_id_tydoc integer, p_document_number character varying, p_mobile character varying, p_id_ptflo integer, p_id_cmpg integer, p_id_hdqts integer, p_to_referral_id bigint, p_comment text) OWNER TO ronald;

--
-- Name: fn_set_attendance_payable(); Type: FUNCTION; Schema: training; Owner: ronald
--

CREATE FUNCTION training.fn_set_attendance_payable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Fin de semana nunca es pagable
    IF EXTRACT(DOW FROM NEW.attendance_date) IN (0, 6) THEN  -- 0=domingo, 6=sábado
        NEW.is_payable    := FALSE;
        NEW.bonus_amount  := 0;
        RETURN NEW;
    END IF;

    -- Días extendidos nunca son pagables
    IF NEW.is_extended = TRUE THEN
        NEW.is_payable   := FALSE;
        NEW.bonus_amount := 0;
        RETURN NEW;
    END IF;

    -- Días normales L-V: pagable solo si el código indica asistencia
    -- (la app debe garantizar que attendance_code_id corresponda a un código válido asistido)
    -- is_payable queda en TRUE por defecto; si fuese falta la app debe enviarlo en FALSE
    NEW.bonus_amount := (
        SELECT g.bonus_per_day
        FROM   training.capa_group g
        INNER JOIN training.capa_group_assigned ga ON ga.group_id = g.id
        WHERE  ga.id = NEW.group_assigned_id
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION training.fn_set_attendance_payable() OWNER TO ronald;

--
-- Name: FUNCTION fn_set_attendance_payable(); Type: COMMENT; Schema: training; Owner: ronald
--

COMMENT ON FUNCTION training.fn_set_attendance_payable() IS 'Calcula automáticamente is_payable y bonus_amount al insertar un registro de asistencia.
Fin de semana o día extendido → is_payable=FALSE, bonus_amount=0.
Día hábil normal → bonus_amount tomado del grupo; is_payable lo define el código de asistencia enviado por la app.';


