--
-- Name: fn_update_capa_control(); Type: FUNCTION; Schema: training; Owner: ronald
--

CREATE FUNCTION training.fn_update_capa_control() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_payable_days          SMALLINT;
    v_extended_days         SMALLINT;
    v_total_days            SMALLINT;
    v_accumulated_bonus     NUMERIC(10,2);
    v_bonus_per_day         NUMERIC(10,2);
    v_start_date            DATE;
    v_cut_period            VARCHAR(10);
    v_bonus_payment_date    DATE;
    v_ref_assigned_id       BIGINT;
    v_ref_date              DATE;
BEGIN
    -- Resolver el registro afectado (NEW en insert/update, OLD en delete lógico)
    v_ref_assigned_id := COALESCE(NEW.group_assigned_id, OLD.group_assigned_id);
    v_ref_date        := COALESCE(NEW.attendance_date,   OLD.attendance_date);

    -- Obtener datos del grupo
    SELECT g.bonus_per_day, g.start_date
    INTO   v_bonus_per_day, v_start_date
    FROM   training.capa_group g
    INNER JOIN training.capa_group_assigned ga ON ga.group_id = g.id
    WHERE  ga.id = v_ref_assigned_id;

    -- Recalcular contando SOLO registros activos
    SELECT
        COUNT(*) FILTER (WHERE is_payable = TRUE  AND is_extended = FALSE AND is_active = TRUE),
        COUNT(*) FILTER (WHERE is_extended = TRUE                         AND is_active = TRUE),
        COUNT(*) FILTER (WHERE                                                is_active = TRUE)
    INTO v_payable_days, v_extended_days, v_total_days
    FROM training.capa_attendance_register
    WHERE group_assigned_id = v_ref_assigned_id;

    v_accumulated_bonus := v_payable_days * v_bonus_per_day;

    -- Determinar corte de bono según día de inicio del grupo
    IF EXTRACT(DAY FROM v_start_date) BETWEEN 1 AND 15 THEN
        v_cut_period         := 'CUT1';
        -- Pago el día 18 del mismo mes
        v_bonus_payment_date := DATE_TRUNC('month', v_start_date) + INTERVAL '17 days';
    ELSE
        v_cut_period         := 'CUT2';
        -- Pago el día 05 del mes siguiente
        v_bonus_payment_date := DATE_TRUNC('month', v_start_date) + INTERVAL '1 month' + INTERVAL '4 days';
    END IF;

    -- UPSERT en capa_control
        group_assigned_id,
        control_date,
        total_days_attended,
        payable_days_attended,
        extended_days_attended,
        accumulated_bonus,
        cut_period,
        bonus_payment_date,
        updated_at
    )
    VALUES (
        v_ref_assigned_id,
        v_ref_date,
        v_total_days,
        v_payable_days,
        v_extended_days,
        v_accumulated_bonus,
        v_cut_period,
        v_bonus_payment_date,
        NOW()
    )
    ON CONFLICT (group_assigned_id, control_date)
    DO UPDATE SET
        total_days_attended     = EXCLUDED.total_days_attended,
        payable_days_attended   = EXCLUDED.payable_days_attended,
        extended_days_attended  = EXCLUDED.extended_days_attended,
        accumulated_bonus       = EXCLUDED.accumulated_bonus,
        cut_period              = EXCLUDED.cut_period,
        bonus_payment_date      = EXCLUDED.bonus_payment_date,
        updated_at              = NOW();

    RETURN NEW;
END;
$$;


ALTER FUNCTION training.fn_update_capa_control() OWNER TO ronald;

--
-- Name: FUNCTION fn_update_capa_control(); Type: COMMENT; Schema: training; Owner: ronald
--

COMMENT ON FUNCTION training.fn_update_capa_control() IS 'Recalcula acumulados en capa_control tras cualquier cambio en capa_attendance_register.
Considera solo registros con is_active = TRUE, por lo que el borrado lógico
(UPDATE SET is_active = FALSE) también dispara el recálculo correctamente.';


--
-- Name: fn_validate_deactivation(); Type: FUNCTION; Schema: training; Owner: ronald
--

CREATE FUNCTION training.fn_validate_deactivation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo actúa cuando is_active pasa de TRUE a FALSE
    IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN

        IF NEW.deactivated_by IS NULL THEN
            RAISE EXCEPTION 'deactivated_by es obligatorio al desactivar un registro (tabla: %)', TG_TABLE_NAME;
        END IF;

        IF NEW.deactivation_reason IS NULL OR TRIM(NEW.deactivation_reason) = '' THEN
            RAISE EXCEPTION 'deactivation_reason es obligatorio al desactivar un registro (tabla: %)', TG_TABLE_NAME;
        END IF;

        -- Registrar timestamp si no viene informado
        IF NEW.deactivated_at IS NULL THEN
            NEW.deactivated_at := NOW();
        END IF;

    END IF;

    -- Bloquear reactivación (is_active no puede volver a TRUE una vez desactivado)
    IF OLD.is_active = FALSE AND NEW.is_active = TRUE THEN
        RAISE EXCEPTION 'No se permite reactivar un registro desactivado (tabla: %). Cree un nuevo registro.', TG_TABLE_NAME;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION training.fn_validate_deactivation() OWNER TO ronald;

--
-- Name: FUNCTION fn_validate_deactivation(); Type: COMMENT; Schema: training; Owner: ronald
--

COMMENT ON FUNCTION training.fn_validate_deactivation() IS 'Valida que todo borrado lógico informe deactivated_by y deactivation_reason.
Además bloquea la reactivación: si un registro fue desactivado, no puede volver a is_active = TRUE.';


--
-- Name: fn_validate_single_active_group(); Type: FUNCTION; Schema: training; Owner: ronald
--

CREATE FUNCTION training.fn_validate_single_active_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    -- Solo valida cuando el registro nuevo está ACTIVE
    IF NEW.status = 'ACTIVE' AND NEW.is_active = TRUE THEN
        SELECT COUNT(*)
        INTO   v_count
        FROM   training.capa_group_assigned
        WHERE  candidate_id = NEW.candidate_id
          AND  status       = 'ACTIVE'
          AND  is_active    = TRUE
          AND  id           <> NEW.id;  -- excluir el propio registro en UPDATE

        IF v_count > 0 THEN
            RAISE EXCEPTION
                'El postulante (candidate_id: %) ya tiene un grupo activo. Cierre el proceso anterior antes de asignar uno nuevo.',
                NEW.candidate_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION training.fn_validate_single_active_group() OWNER TO ronald;

