--
-- Name: v_today_schedule_vs_mark; Type: VIEW; Schema: attendance; Owner: ronald
--

CREATE VIEW attendance.v_today_schedule_vs_mark AS
 WITH usercycle AS (
         SELECT us.id_user,
            us.id_sch_tpl,
            EXTRACT(dow FROM CURRENT_DATE) AS today_cycle_day
           FROM planilla.user_schedules us
          WHERE ((us.state = true) AND (us.start_date <= CURRENT_DATE) AND ((us.end_date IS NULL) OR (us.end_date >= CURRENT_DATE)))
        ), todayschedule AS (
         SELECT uc.id_user,
            ste.entry_time AS scheduled_entry,
            ste.exit_time AS scheduled_exit
           FROM (usercycle uc
             JOIN planilla.schedule_template_entries ste ON (((ste.id_sch_tpl = uc.id_sch_tpl) AND ((ste.identifier_day)::numeric = uc.today_cycle_day))))
          WHERE (ste.state = true)
        ), todayattendance AS (
         SELECT ar.id_user,
            ar.entry_time AS marked_entry,
            ar.exit_time AS marked_exit
           FROM attendance.attendance_register ar
          WHERE (ar.date = CURRENT_DATE)
        )
 SELECT ts.id_user,
    ts.scheduled_entry,
    ta.marked_entry,
    ts.scheduled_exit,
    ta.marked_exit
   FROM (todayschedule ts
     LEFT JOIN todayattendance ta ON ((ta.id_user = ts.id_user)));


ALTER VIEW attendance.v_today_schedule_vs_mark OWNER TO ronald;

--
-- Name: v_today_early_exits; Type: VIEW; Schema: attendance; Owner: ronald
--

CREATE VIEW attendance.v_today_early_exits AS
 SELECT id_user,
    scheduled_exit AS scheduled_exit_time,
    marked_exit AS marked_exit_time
   FROM attendance.v_today_schedule_vs_mark
  WHERE ((marked_exit IS NOT NULL) AND (marked_exit < scheduled_exit));


ALTER VIEW attendance.v_today_early_exits OWNER TO ronald;

--
-- Name: v_today_valid_exits; Type: VIEW; Schema: attendance; Owner: ronald
--

CREATE VIEW attendance.v_today_valid_exits AS
 SELECT id_user,
    scheduled_exit AS scheduled_exit_time,
    marked_exit AS marked_exit_time
   FROM attendance.v_today_schedule_vs_mark
  WHERE ((marked_exit IS NOT NULL) AND (marked_exit >= scheduled_exit));


ALTER VIEW attendance.v_today_valid_exits OWNER TO ronald;

