--
-- Name: vw_active_sessions; Type: VIEW; Schema: bi_i; Owner: ronald
--

CREATE VIEW bi_i.vw_active_sessions AS
 SELECT log.id_biiacclog,
    log.id_user,
    TRIM(BOTH FROM (((((COALESCE(u.name, ''::character varying))::text || ' '::text) || (COALESCE(u.paternal_surname, ''::character varying))::text) || ' '::text) || (COALESCE(u.maternal_surname, ''::character varying))::text)) AS full_name,
    log.id_biiurl,
    rpt.description AS report_name,
    log.start_time,
    (CURRENT_TIMESTAMP - (log.start_time)::timestamp with time zone) AS duration_so_far
   FROM ((bi_i.bii_access_log log
     JOIN planilla.mother_data u ON ((log.id_user = u.id_user)))
     JOIN bi_i.bii_url rpt ON ((log.id_biiurl = rpt.id_biiurl)))
  WHERE (log.end_time IS NULL);


ALTER VIEW bi_i.vw_active_sessions OWNER TO ronald;

--
-- Name: vw_report_status; Type: VIEW; Schema: bi_i; Owner: ronald
--

CREATE VIEW bi_i.vw_report_status AS
 SELECT u.id_biiurl,
    u.url,
    gr.id_biigprpt,
    gr.name AS group_name,
        CASE
            WHEN (active_maint.id_biimaint IS NOT NULL) THEN true
            ELSE false
        END AS is_updating,
    COALESCE(active_maint.title, 'Disponible'::character varying) AS status_title,
    active_maint.message AS status_message,
    active_maint.start_time AS maintenance_start
   FROM (((bi_i.bii_url u
     JOIN bi_i.bii_group bg ON (((u.id_biiurl = bg.id_biiurl) AND (bg.state = 1))))
     JOIN bi_i.bii_group_report gr ON (((bg.id_biigprpt = gr.id_biigprpt) AND (gr.state = 1))))
     LEFT JOIN ( SELECT ms.id_biiurl,
            ms.id_biigprpt,
            me.id_biimaint,
            me.title,
            me.message,
            me.start_time
           FROM (bi_i.bii_maintenance_scope ms
             JOIN bi_i.bii_maintenance_event me ON ((ms.id_biimaint = me.id_biimaint)))
          WHERE ((me.state = 1) AND (me.start_time <= CURRENT_TIMESTAMP) AND ((me.end_time IS NULL) OR (me.end_time > CURRENT_TIMESTAMP)))) active_maint ON (((active_maint.id_biiurl = u.id_biiurl) OR (active_maint.id_biigprpt = gr.id_biigprpt))));


ALTER VIEW bi_i.vw_report_status OWNER TO ronald;

--
-- Name: vw_usage_history; Type: VIEW; Schema: bi_i; Owner: ronald
--

CREATE VIEW bi_i.vw_usage_history AS
 SELECT log.id_biiacclog,
    log.id_user,
    u.name,
    u.paternal_surname,
    u.maternal_surname,
    rpt.description AS report_name,
    rpt.url,
    log.start_time,
    log.end_time,
        CASE
            WHEN (log.end_time IS NOT NULL) THEN (log.end_time - log.start_time)
            ELSE (CURRENT_TIMESTAMP - (log.start_time)::timestamp with time zone)
        END AS session_duration,
        CASE
            WHEN (log.end_time IS NULL) THEN 'ACTIVO'::text
            ELSE 'CERRADO'::text
        END AS status_label
   FROM ((bi_i.bii_access_log log
     JOIN planilla.mother_data u ON ((log.id_user = u.id_user)))
     JOIN bi_i.bii_url rpt ON ((log.id_biiurl = rpt.id_biiurl)));


ALTER VIEW bi_i.vw_usage_history OWNER TO ronald;

