--
-- Name: v_estructura_jerarquica; Type: VIEW; Schema: business_hierarchy; Owner: ronald
--

CREATE VIEW business_hierarchy.v_estructura_jerarquica AS
 WITH RECURSIVE jerarquia AS (
         SELECT sd.id_strtdiv,
            sd.name AS division_name,
            sl.name AS level_name,
            sd.id_strtlvl,
            sd.parent_id,
            1 AS depth,
            (sd.name)::text AS path,
            ARRAY[sd.id_strtdiv] AS id_path,
            ARRAY[(sd.name)::text] AS name_path
           FROM (business_hierarchy.structural_divisions sd
             JOIN business_hierarchy.structural_level sl ON ((sl.id_strtlvl = sd.id_strtlvl)))
          WHERE ((sd.parent_id IS NULL) AND (sd.state = 1) AND (sl.state = 1))
        UNION ALL
         SELECT h.id_strtdiv,
            h.name AS division_name,
            sl.name AS level_name,
            h.id_strtlvl,
            h.parent_id,
            (j_1.depth + 1) AS depth,
            ((j_1.path || ' > '::text) || (h.name)::text) AS path,
            (j_1.id_path || h.id_strtdiv),
            (j_1.name_path || (h.name)::text)
           FROM ((business_hierarchy.structural_divisions h
             JOIN business_hierarchy.structural_level sl ON ((sl.id_strtlvl = h.id_strtlvl)))
             JOIN jerarquia j_1 ON ((j_1.id_strtdiv = h.parent_id)))
          WHERE ((h.state = 1) AND (sl.state = 1))
        )
 SELECT id_strtdiv,
    division_name,
    level_name,
    id_strtlvl,
    parent_id,
    depth,
    path,
    id_path,
    name_path,
    id_path[1] AS id_nivel_1,
    name_path[1] AS nombre_nivel_1,
    id_path[2] AS id_nivel_2,
    name_path[2] AS nombre_nivel_2,
    id_path[3] AS id_nivel_3,
    name_path[3] AS nombre_nivel_3,
    id_path[4] AS id_nivel_4,
    name_path[4] AS nombre_nivel_4
   FROM jerarquia j
  ORDER BY path;


ALTER VIEW business_hierarchy.v_estructura_jerarquica OWNER TO ronald;

--
-- Name: vw_hierarchy_dashboard; Type: VIEW; Schema: business_hierarchy; Owner: ronald
--

CREATE VIEW business_hierarchy.vw_hierarchy_dashboard AS
 WITH RECURSIVE jerarquia AS (
         SELECT sd.id_strtdiv,
            sd.name AS division_name,
            sl.name AS level_name,
            sd.parent_id,
            1 AS depth,
            (sd.name)::text AS path,
            ARRAY[sd.id_strtdiv] AS sort_path
           FROM (business_hierarchy.structural_divisions sd
             JOIN business_hierarchy.structural_level sl ON ((sl.id_strtlvl = sd.id_strtlvl)))
          WHERE ((sd.parent_id IS NULL) AND (sd.state = 1))
        UNION ALL
         SELECT h.id_strtdiv,
            h.name AS division_name,
            sl.name AS level_name,
            h.parent_id,
            (j.depth + 1),
            ((j.path || ' > '::text) || (h.name)::text),
            (j.sort_path || h.id_strtdiv)
           FROM ((business_hierarchy.structural_divisions h
             JOIN business_hierarchy.structural_level sl ON ((sl.id_strtlvl = h.id_strtlvl)))
             JOIN jerarquia j ON ((j.id_strtdiv = h.parent_id)))
          WHERE (h.state = 1)
        )
 SELECT id_strtdiv,
    division_name,
    level_name,
    depth,
    ((repeat('    '::text, (depth - 1)) ||
        CASE depth
            WHEN 1 THEN '● '::text
            WHEN 2 THEN '─ '::text
            WHEN 3 THEN '• '::text
            WHEN 4 THEN '→ '::text
            ELSE '» '::text
        END) || (division_name)::text) AS estructura
   FROM jerarquia
  ORDER BY sort_path;


ALTER VIEW business_hierarchy.vw_hierarchy_dashboard OWNER TO ronald;

--
-- Name: vw_user_hierarchy; Type: VIEW; Schema: business_hierarchy; Owner: ronald
--

CREATE VIEW business_hierarchy.vw_user_hierarchy AS
 WITH RECURSIVE user_hierarchy_cte AS (
         SELECT bi.id_user,
            sd.id_strtdiv,
            sd.name AS division_name,
            sd.parent_id,
            sl.level AS level_number
           FROM ((business_hierarchy.business_information bi
             JOIN business_hierarchy.structural_divisions sd ON ((bi.id_strtdiv = sd.id_strtdiv)))
             JOIN business_hierarchy.structural_level sl ON ((sd.id_strtlvl = sl.id_strtlvl)))
          WHERE ((bi.state = 1) AND (sd.state = 1) AND (sl.state = 1))
        UNION ALL
         SELECT cte_1.id_user,
            parent_sd.id_strtdiv,
            parent_sd.name AS division_name,
            parent_sd.parent_id,
            parent_sl.level AS level_number
           FROM ((user_hierarchy_cte cte_1
             JOIN business_hierarchy.structural_divisions parent_sd ON ((cte_1.parent_id = parent_sd.id_strtdiv)))
             JOIN business_hierarchy.structural_level parent_sl ON ((parent_sd.id_strtlvl = parent_sl.id_strtlvl)))
          WHERE ((parent_sd.state = 1) AND (parent_sl.state = 1))
        )
 SELECT cte.id_user,
    planilla.get_formatted_mother_name((md.name)::text, (md.paternal_surname)::text, (md.maternal_surname)::text, 'Proper'::text) AS nombre_formateado,
    (max((
        CASE
            WHEN (cte.level_number = 1) THEN cte.division_name
            ELSE NULL::character varying
        END)::text))::character varying AS nivel_1_departamento,
    (max((
        CASE
            WHEN (cte.level_number = 2) THEN cte.division_name
            ELSE NULL::character varying
        END)::text))::character varying AS nivel_2_area,
    (max((
        CASE
            WHEN (cte.level_number = 3) THEN cte.division_name
            ELSE NULL::character varying
        END)::text))::character varying AS nivel_3_subarea,
    (max((
        CASE
            WHEN (cte.level_number = 4) THEN cte.division_name
            ELSE NULL::character varying
        END)::text))::character varying AS nivel_4_cargo,
    jsonb_build_object('departamento', jsonb_build_object('id', max(
        CASE
            WHEN (cte.level_number = 1) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END), 'nombre', max((
        CASE
            WHEN (cte.level_number = 1) THEN cte.division_name
            ELSE NULL::character varying
        END)::text)), 'area', jsonb_build_object('id', max(
        CASE
            WHEN (cte.level_number = 2) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END), 'nombre', max((
        CASE
            WHEN (cte.level_number = 2) THEN cte.division_name
            ELSE NULL::character varying
        END)::text)), 'subarea', jsonb_build_object('id', max(
        CASE
            WHEN (cte.level_number = 3) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END), 'nombre', max((
        CASE
            WHEN (cte.level_number = 3) THEN cte.division_name
            ELSE NULL::character varying
        END)::text)), 'cargo', jsonb_build_object('id', max(
        CASE
            WHEN (cte.level_number = 4) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END), 'nombre', max((
        CASE
            WHEN (cte.level_number = 4) THEN cte.division_name
            ELSE NULL::character varying
        END)::text))) AS jerarquia_json,
    max(
        CASE
            WHEN (cte.level_number = 1) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END) AS id_departamento,
    max(
        CASE
            WHEN (cte.level_number = 2) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END) AS id_area,
    max(
        CASE
            WHEN (cte.level_number = 3) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END) AS id_subarea,
    max(
        CASE
            WHEN (cte.level_number = 4) THEN cte.id_strtdiv
            ELSE NULL::bigint
        END) AS id_cargo
   FROM (user_hierarchy_cte cte
     LEFT JOIN planilla.mother_data md ON ((cte.id_user = md.id_user)))
  GROUP BY cte.id_user, (planilla.get_formatted_mother_name((md.name)::text, (md.paternal_surname)::text, (md.maternal_surname)::text, 'Proper'::text));


