--
-- Name: v_sphere_users; Type: VIEW; Schema: credentials; Owner: postgres
--

CREATE VIEW credentials.v_sphere_users AS
 SELECT md.id_user,
    md.document_number,
    md.name AS first_name,
    TRIM(BOTH FROM ((COALESCE(NULLIF((md.paternal_surname)::text, ''::text), ''::text) ||
        CASE
            WHEN ((md.paternal_surname IS NOT NULL) AND ((md.paternal_surname)::text <> ''::text) AND (md.maternal_surname IS NOT NULL) AND ((md.maternal_surname)::text <> ''::text)) THEN ' '::text
            ELSE ''::text
        END) || COALESCE(NULLIF((md.maternal_surname)::text, ''::text), ''::text))) AS last_name,
    mif.mail AS email,
    tif.phone
   FROM ((planilla.mother_data md
     JOIN planilla.mail_information mif ON (((mif.id_user = md.id_user) AND (mif.main = true) AND (mif.state = 1))))
     JOIN planilla.telephone_information tif ON (((tif.id_user = md.id_user) AND (tif.main = true) AND (tif.state = 1))))
  WHERE (md.state = 1)
  ORDER BY md.id_user;


ALTER VIEW credentials.v_sphere_users OWNER TO postgres;

--
-- Name: vw_historial_logs; Type: VIEW; Schema: credentials; Owner: ronald
--

CREATE VIEW credentials.vw_historial_logs AS
 SELECT sl.id_user,
    COALESCE((((((md.name)::text || ' '::text) || (md.paternal_surname)::text) || ' '::text) || (md.maternal_surname)::text), 'Usuario sin datos'::text) AS full_name,
    sl.ip_public,
    sl.ip_local,
    sl.mac,
    sl.whoami,
    (sl.register)::date AS date,
    (sl.register)::time without time zone AS "time",
    'success'::text AS type_event
   FROM (credentials.session_log sl
     LEFT JOIN planilla.mother_data md ON ((sl.id_user = md.id_user)))
UNION ALL
 SELECT c.id_user,
    COALESCE((((((md.name)::text || ' '::text) || (md.paternal_surname)::text) || ' '::text) || (md.maternal_surname)::text), (sal.username)::text) AS full_name,
    sal.ip_public,
    sal.ip_local,
    sal.mac,
    sal.whoami,
    (sal.register)::date AS date,
    (sal.register)::time without time zone AS "time",
    'attempt'::text AS type_event
   FROM ((credentials.session_attempt_log sal
     LEFT JOIN credentials.credentials c ON ((lower(bi_i.unaccent(TRIM(BOTH FROM sal.username))) = lower(bi_i.unaccent(TRIM(BOTH FROM c.username))))))
     LEFT JOIN planilla.mother_data md ON ((c.id_user = md.id_user)))
  WHERE (c.id_user IS NOT NULL);


ALTER VIEW credentials.vw_historial_logs OWNER TO ronald;

--
-- Name: vw_anomalias_ip_mensual; Type: VIEW; Schema: credentials; Owner: ronald
--

CREATE VIEW credentials.vw_anomalias_ip_mensual AS
 WITH tendencia_mensual AS (
         SELECT vw_historial_logs.id_user,
            to_char((vw_historial_logs.date)::timestamp with time zone, 'YYYY-MM'::text) AS mes_anio,
            vw_historial_logs.ip_local AS ip_tendencia,
            row_number() OVER (PARTITION BY vw_historial_logs.id_user, (to_char((vw_historial_logs.date)::timestamp with time zone, 'YYYY-MM'::text)) ORDER BY (count(*)) DESC) AS rn
           FROM credentials.vw_historial_logs
          WHERE (vw_historial_logs.type_event = 'success'::text)
          GROUP BY vw_historial_logs.id_user, (to_char((vw_historial_logs.date)::timestamp with time zone, 'YYYY-MM'::text)), vw_historial_logs.ip_local
        ), trend_filter AS (
         SELECT tendencia_mensual.id_user,
            tendencia_mensual.mes_anio,
            tendencia_mensual.ip_tendencia
           FROM tendencia_mensual
          WHERE (tendencia_mensual.rn = 1)
        )
 SELECT h.id_user,
    h.full_name,
    h.ip_local AS ip_actual,
    t.ip_tendencia AS ip_esperada_mes,
    h.ip_public,
    h.mac,
    h.whoami,
    h.date,
    h."time",
    h.type_event,
        CASE
            WHEN ((h.ip_local)::text = (t.ip_tendencia)::text) THEN 'normal'::text
            ELSE 'fuera_de_tendencia'::text
        END AS estado_registro
   FROM (credentials.vw_historial_logs h
     JOIN trend_filter t ON (((h.id_user = t.id_user) AND (to_char((h.date)::timestamp with time zone, 'YYYY-MM'::text) = t.mes_anio))))
  WHERE ((h.ip_local)::text <> (t.ip_tendencia)::text)
  ORDER BY h.date DESC, h."time" DESC;


ALTER VIEW credentials.vw_anomalias_ip_mensual OWNER TO ronald;

--
-- Name: vw_ip_frecuente_usuario; Type: VIEW; Schema: credentials; Owner: ronald
--

CREATE VIEW credentials.vw_ip_frecuente_usuario AS
 WITH conteo_ips AS (
         SELECT vw_historial_logs.id_user,
            vw_historial_logs.full_name,
            vw_historial_logs.ip_local,
            vw_historial_logs.ip_public,
            count(*) AS frecuencia,
            max(vw_historial_logs.date) AS ultimo_acceso_fecha,
            max(vw_historial_logs."time") AS ultimo_acceso_hora,
            row_number() OVER (PARTITION BY vw_historial_logs.id_user ORDER BY (count(*)) DESC) AS rn
           FROM credentials.vw_historial_logs
          WHERE (vw_historial_logs.type_event = 'success'::text)
          GROUP BY vw_historial_logs.id_user, vw_historial_logs.full_name, vw_historial_logs.ip_local, vw_historial_logs.ip_public
        )
 SELECT id_user,
    full_name,
    ip_local AS ip_mas_usada,
    ip_public,
    frecuencia AS cantidad_accesos,
    ultimo_acceso_fecha AS date,
    ultimo_acceso_hora AS "time",
    'tendencia_global'::text AS type_event
   FROM conteo_ips
  WHERE (rn = 1);


ALTER VIEW credentials.vw_ip_frecuente_usuario OWNER TO ronald;

