    id_empleado integer DEFAULT nextval('huellero.huellero_id_empleado_seq'::regclass),
    fecha_hora_acceso timestamp(6) without time zone,
    fecha_acceso date,
    hora_acceso time(6) without time zone,
    nombre_persona character varying(255)
);


ALTER TABLE huellero.huellero OWNER TO ronald;

--
-- Name: v_huellero_reg; Type: VIEW; Schema: huellero; Owner: ronald
--

CREATE VIEW huellero.v_huellero_reg AS
 WITH accesos_ordenados AS (
         SELECT huellero.id_empleado,
            huellero.fecha_acceso,
            huellero.hora_acceso,
            row_number() OVER (PARTITION BY huellero.id_empleado, huellero.fecha_acceso ORDER BY huellero.hora_acceso) AS rn_primero,
            row_number() OVER (PARTITION BY huellero.id_empleado, huellero.fecha_acceso ORDER BY huellero.hora_acceso DESC) AS rn_ultimo
           FROM huellero.huellero
        ), entradas_salidas AS (
         SELECT accesos_ordenados.id_empleado,
            accesos_ordenados.fecha_acceso,
            max(
                CASE
                    WHEN (accesos_ordenados.rn_primero = 1) THEN accesos_ordenados.hora_acceso
                    ELSE NULL::time without time zone
                END) AS entrada,
            max(
                CASE
                    WHEN (accesos_ordenados.rn_ultimo = 1) THEN accesos_ordenados.hora_acceso
                    ELSE NULL::time without time zone
                END) AS salida
           FROM accesos_ordenados
          WHERE ((accesos_ordenados.rn_primero = 1) OR (accesos_ordenados.rn_ultimo = 1))
          GROUP BY accesos_ordenados.id_empleado, accesos_ordenados.fecha_acceso
        )
 SELECT id_empleado AS id_user,
    fecha_acceso AS fecha,
    entrada,
        CASE
            WHEN (salida > (entrada + '00:20:00'::interval)) THEN salida
            ELSE NULL::time without time zone
        END AS salida
   FROM entradas_salidas
  ORDER BY id_empleado, fecha_acceso;


ALTER VIEW huellero.v_huellero_reg OWNER TO ronald;

--
-- Name: v_login; Type: VIEW; Schema: huellero; Owner: ronald
--

CREATE VIEW huellero.v_login AS
 SELECT DISTINCT cdt.id_user,
    true AS marcacion
   FROM (credentials.credentials cdt
     JOIN huellero.huellero h ON ((h.id_empleado = cdt.id_user)))
  WHERE ((cdt.state = 1) AND (h.fecha_acceso = CURRENT_DATE));


ALTER VIEW huellero.v_login OWNER TO ronald;

