    description text,
    status_label character varying(50) DEFAULT 'To Do'::character varying,
    priority nx_project.task_priority DEFAULT 'medium'::nx_project.task_priority,
    percent_complete smallint DEFAULT 0,
    start_date timestamp with time zone,
    end_date timestamp with time zone,
    duration_hours numeric(10,2),
    is_milestone boolean DEFAULT false,
    sprint_id bigint,
    story_points smallint DEFAULT 0,
    row_index integer DEFAULT 0 NOT NULL,
    custom_attributes jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT tasks_percent_complete_check CHECK (((percent_complete >= 0) AND (percent_complete <= 100)))
);


