--
-- Name: view_agile_tasks; Type: VIEW; Schema: nx_project; Owner: ronald
--

CREATE VIEW nx_project.view_agile_tasks AS
 SELECT t.task_id,
    t.project_id,
    t.title,
    t.status_label,
    t.priority,
    t.story_points,
    t.sprint_id,
    s.name AS sprint_name,
    s.is_active AS sprint_is_active
   FROM (nx_project.tasks t
     LEFT JOIN nx_project.sprints s ON ((t.sprint_id = s.sprint_id)));


ALTER VIEW nx_project.view_agile_tasks OWNER TO ronald;

--
-- Name: view_project_summary; Type: VIEW; Schema: nx_project; Owner: ronald
--

CREATE VIEW nx_project.view_project_summary AS
 SELECT p.project_id,
    p.name AS project_name,
    p.status,
    p.total_budget,
    COALESCE(sum(pc.amount), (0)::numeric) AS total_actual_cost,
    (p.total_budget - COALESCE(sum(pc.amount), (0)::numeric)) AS budget_variance,
    count(t.task_id) AS total_tasks,
    count(
        CASE
            WHEN (t.percent_complete = 100) THEN 1
            ELSE NULL::integer
        END) AS completed_tasks,
    round(avg(COALESCE((t.percent_complete)::integer, 0)), 2) AS avg_project_progress
   FROM ((nx_project.projects p
     LEFT JOIN nx_project.tasks t ON ((p.project_id = t.project_id)))
     LEFT JOIN nx_project.project_costs pc ON ((p.project_id = pc.project_id)))
  GROUP BY p.project_id, p.name, p.status, p.total_budget;


ALTER VIEW nx_project.view_project_summary OWNER TO ronald;

