--
-- Name: v_colaboradores_division; Type: VIEW; Schema: planilla; Owner: ronald
--

CREATE VIEW planilla.v_colaboradores_division AS
 SELECT u.id_user AS id_colaborador,
    TRIM(BOTH FROM (((((u.name)::text || ' '::text) || (COALESCE(u.paternal_surname, ''::character varying))::text) || ' '::text) || (COALESCE(u.maternal_surname, ''::character varying))::text)) AS nombre_colaborador,
    sd_dpto.name AS division
   FROM (((planilla.mother_data u
     LEFT JOIN business_hierarchy.business_information bi ON (((bi.id_user = u.id_user) AND (bi.state = 1))))
     LEFT JOIN business_hierarchy.structural_divisions sd_cargo ON ((sd_cargo.id_strtdiv = bi.id_strtdiv)))
     LEFT JOIN business_hierarchy.structural_divisions sd_dpto ON ((sd_dpto.id_strtdiv = sd_cargo.parent_id)))
  WHERE (u.state = 1);


ALTER VIEW planilla.v_colaboradores_division OWNER TO ronald;

