--
-- Name: vw_colaborador_supervisor; Type: VIEW; Schema: planilla; Owner: ronald
--

CREATE VIEW planilla.vw_colaborador_supervisor AS
 SELECT mem.id_user AS id_colaborador,
    TRIM(BOTH FROM ((split_part((md_colab.name)::text, ' '::text, 1) || ' '::text) || COALESCE(NULLIF((md_colab.paternal_surname)::text, ''::text), (md_colab.maternal_surname)::text))) AS nombre_colaborador,
    TRIM(BOTH FROM ((split_part((md_super.name)::text, ' '::text, 1) || ' '::text) || COALESCE(NULLIF((md_super.paternal_surname)::text, ''::text), (md_super.maternal_surname)::text))) AS nombre_supervisor,
    mgr.id_role AS id_rol_supervisor,
    mem.id_group,
    mem.entry_date
   FROM (((groups.group_members mem
     JOIN groups.group_managers mgr ON ((mem.id_group = mgr.id_group)))
     JOIN planilla.mother_data md_colab ON ((mem.id_user = md_colab.id_user)))
     JOIN planilla.mother_data md_super ON ((mgr.id_user = md_super.id_user)))
  WHERE ((mem.state = 1) AND (mgr.state = 1) AND (mgr.id_role = ANY (ARRAY[1, 2])) AND (mem.id_user <> mgr.id_user));


ALTER VIEW planilla.vw_colaborador_supervisor OWNER TO ronald;

