--
-- Name: vw_user_trajectory_ext; Type: VIEW; Schema: trajectory; Owner: ronald
--

CREATE VIEW trajectory.vw_user_trajectory_ext AS
 SELECT uty.id_user,
    ety.name,
    ety.order_event,
    uty.event_date,
    uty.related_schema,
    uty.related_table,
    uty.related_id,
    uty.register_at,
    uty.state
   FROM (trajectory.user_trajectory uty
     JOIN trajectory.event_types ety ON ((uty.id_evty = ety.id_evty)))
  WHERE ((ety.state = true) AND (uty.state = true));


ALTER VIEW trajectory.vw_user_trajectory_ext OWNER TO ronald;

