-- Name: vw_user_hierarchy_base; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_user_hierarchy_base AS
 WITH RECURSIVE user_hierarchy_cte AS (
         SELECT bi.id_user,
            sd.id_strtdiv,
            sd.name AS division_name,
            sd.parent_id,
            sl.level AS level_number
           FROM ((business_hierarchy.business_information bi
             JOIN business_hierarchy.structural_divisions sd ON ((bi.id_strtdiv = sd.id_strtdiv)))
             JOIN business_hierarchy.structural_level sl ON ((sd.id_strtlvl = sl.id_strtlvl)))
          WHERE ((bi.state = 1) AND (sd.state = 1) AND (sl.state = 1))
        UNION ALL
         SELECT c.id_user,
            parent_sd.id_strtdiv,
            parent_sd.name AS division_name,
            parent_sd.parent_id,
            parent_sl.level AS level_number
           FROM ((user_hierarchy_cte c
             JOIN business_hierarchy.structural_divisions parent_sd ON ((c.parent_id = parent_sd.id_strtdiv)))
             JOIN business_hierarchy.structural_level parent_sl ON ((parent_sd.id_strtlvl = parent_sl.id_strtlvl)))
          WHERE ((parent_sd.state = 1) AND (parent_sl.state = 1))
        )
 SELECT cte.id_user,
    md.birthday,
    concat(md.name, ' ', COALESCE(NULLIF((md.paternal_surname)::text, ''::text), (md.maternal_surname)::text, ''::text)) AS full_name,
    COALESCE(pu.rounded_photo_path, pd.path_location) AS photo_url,
    max((
        CASE
            WHEN (cte.level_number = 1) THEN cte.division_name
            ELSE NULL::character varying
        END)::text) AS departamento,
    max((
        CASE
            WHEN (cte.level_number = 2) THEN cte.division_name
            ELSE NULL::character varying
        END)::text) AS area,
    max((
        CASE
            WHEN (cte.level_number = 4) THEN cte.division_name
            ELSE NULL::character varying
        END)::text) AS cargo
   FROM (((user_hierarchy_cte cte
     LEFT JOIN planilla.mother_data md ON ((cte.id_user = md.id_user)))
     LEFT JOIN photograph.photos_user pu ON (((cte.id_user = pu.id_user) AND (pu.state = 1))))
     LEFT JOIN photograph.photo_default pd ON ((pu.id_dfpht = pd.id_dfpht)))
  WHERE (md.state = 1)
  GROUP BY cte.id_user, md.birthday, md.name, md.paternal_surname, md.maternal_surname, pu.rounded_photo_path, pd.path_location;


ALTER VIEW work_environment.vw_user_hierarchy_base OWNER TO ronald;

--
-- Name: vw_birthday_management_dashboard; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_birthday_management_dashboard AS
 SELECT u.id_user,
    u.full_name,
    u.departamento,
    u.cargo,
    u.area,
    u.photo_url,
    u.birthday,
    EXTRACT(month FROM u.birthday) AS birth_month,
    EXTRACT(day FROM u.birthday) AS birth_day,
    ep.id_participant,
    ev.id_event,
    COALESCE(ep.attendance_status, 'NOT_PLANNED'::character varying) AS status_gestion,
    ( SELECT sum(pra.actual_cost) AS sum
           FROM work_environment.participant_resource_allocations pra
          WHERE (pra.id_participant = ep.id_participant)) AS total_invertido
   FROM ((work_environment.vw_user_hierarchy_base u
     LEFT JOIN work_environment.event_participants ep ON ((u.id_user = ep.id_user)))
     LEFT JOIN work_environment.celebration_events ev ON (((ep.id_event = ev.id_event) AND (ev.id_event_type = ( SELECT event_types.id_event_type
           FROM work_environment.event_types
          WHERE ((event_types.name)::text = 'Cumpleaños'::text)
         LIMIT 1)))));


ALTER VIEW work_environment.vw_birthday_management_dashboard OWNER TO ronald;

--
-- Name: vw_enps_analytics; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_enps_analytics AS
 SELECT l.id_launch,
    l.name AS survey_name,
    l.end_date,
    count(a.id_answer) AS total_responses,
    count(
        CASE
            WHEN (a.score_value >= 9) THEN 1
            ELSE NULL::integer
        END) AS promoters,
    count(
        CASE
            WHEN ((a.score_value >= 7) AND (a.score_value <= 8)) THEN 1
            ELSE NULL::integer
        END) AS passives,
    count(
        CASE
            WHEN (a.score_value <= 6) THEN 1
            ELSE NULL::integer
        END) AS detractors,
    round(((((count(
        CASE
            WHEN (a.score_value >= 9) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(a.id_answer), 0))::numeric) * (100)::numeric) - (((count(
        CASE
            WHEN (a.score_value <= 6) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(a.id_answer), 0))::numeric) * (100)::numeric)), 2) AS enps_score
   FROM (((work_environment.survey_launches l
     JOIN work_environment.survey_responses r ON ((l.id_launch = r.id_launch)))
     JOIN work_environment.survey_answers a ON ((r.id_response = a.id_response)))
     JOIN work_environment.survey_questions q ON ((a.id_question = q.id_question)))
  WHERE (((q.question_type)::text = 'NPS'::text) AND (l.state = 1))
  GROUP BY l.id_launch, l.name, l.end_date;


ALTER VIEW work_environment.vw_enps_analytics OWNER TO ronald;

--
-- Name: vw_public_suggestions; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_public_suggestions AS
 SELECT id_suggestion,
    subject,
    category,
    status,
    created_at,
        CASE
            WHEN publish_response_only THEN 'El contenido de esta sugerencia es privado, pero la respuesta es de interés general.'::text
            ELSE message
        END AS visible_message,
    admin_response
   FROM work_environment.suggestion_box sb
  WHERE ((state = 1) AND (is_publicly_visible = true));


ALTER VIEW work_environment.vw_public_suggestions OWNER TO ronald;

--
-- Name: vw_recognition_feed; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_recognition_feed AS
 SELECT r.id_recognition,
    sender.full_name AS sender_name,
    sender.photo_url AS sender_photo,
        CASE
            WHEN (r.receiver_user_id IS NOT NULL) THEN receiver.full_name
            WHEN (r.receiver_group_id IS NOT NULL) THEN (g.name_group)::text
            ELSE 'Desconocido'::text
        END AS receiver_name,
    cv.name AS core_value,
    cv.icon_url,
    r.message,
    r.created_at
   FROM ((((work_environment.recognitions r
     JOIN work_environment.vw_user_hierarchy_base sender ON ((r.sender_user_id = sender.id_user)))
     LEFT JOIN work_environment.vw_user_hierarchy_base receiver ON ((r.receiver_user_id = receiver.id_user)))
     LEFT JOIN work_environment.core_values cv ON ((r.id_core_value = cv.id_core_value)))
     LEFT JOIN groups."group" g ON ((r.receiver_group_id = g.id_group)))
  WHERE ((r.state = 1) AND (r.is_public = true))
  ORDER BY r.created_at DESC;


ALTER VIEW work_environment.vw_recognition_feed OWNER TO ronald;

--
-- Name: vw_resource_financial_analysis; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_resource_financial_analysis AS
 SELECT ev.id_event,
    ev.name AS event_name,
    u.full_name AS beneficiario,
    res.name AS item,
    pra.delivery_status,
    pra.budgeted_amount AS presupuesto,
    pra.actual_cost AS costo_real,
        CASE
            WHEN ((pra.delivery_status)::text = ANY (ARRAY[('NOT_DELIVERED_SAVED'::character varying)::text, ('RETURNED_TO_STOCK'::character varying)::text])) THEN pra.budgeted_amount
            ELSE (pra.budgeted_amount - pra.actual_cost)
        END AS saldo_a_favor,
    pra.reason_for_change
   FROM ((((work_environment.participant_resource_allocations pra
     JOIN work_environment.event_participants ep ON ((pra.id_participant = ep.id_participant)))
     JOIN work_environment.celebration_events ev ON ((ep.id_event = ev.id_event)))
     JOIN work_environment.vw_user_hierarchy_base u ON ((ep.id_user = u.id_user)))
     JOIN work_environment.resource_catalog res ON ((pra.id_resource = res.id_resource)));


ALTER VIEW work_environment.vw_resource_financial_analysis OWNER TO ronald;

