ALTER TABLE work_environment.wellness_programs OWNER TO ronald;

--
-- Name: vw_wellness_participation_stats; Type: VIEW; Schema: work_environment; Owner: ronald
--

CREATE VIEW work_environment.vw_wellness_participation_stats AS
 SELECT wp.id_program,
    wp.name AS program_name,
    wc.name AS category,
    wp.start_date,
    count(part.id_participation) AS total_inscritos,
    round((((count(
        CASE
            WHEN ((part.attendance_status)::text = 'ATTENDED'::text) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(part.id_participation), 0))::numeric) * (100)::numeric), 2) AS tasa_asistencia_percent,
    round(avg(part.rating), 1) AS rating_promedio
   FROM ((work_environment.wellness_programs wp
     JOIN work_environment.wellness_categories wc ON ((wp.id_wellness_cat = wc.id_wellness_cat)))
     LEFT JOIN work_environment.wellness_participation part ON ((wp.id_program = part.id_program)))
  WHERE (wp.state = 1)
  GROUP BY wp.id_program, wp.name, wc.name, wp.start_date;


ALTER VIEW work_environment.vw_wellness_participation_stats OWNER TO ronald;

